(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0026.js"] = [{"id":"poem-aadbeadadc57f5effc9dea73","title":"汉宫词","author":"李益","dynasty":"唐","verses":["汉室长陵小市东，珠帘绣户对春风。","君王昨日移仙仗，玉辇将迎入汉中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-03aceab2-1bbe-4c0f-850b-b98d3760e35a","tags":[]},{"id":"poem-aaddc36b204c90a7bd454695","title":"忆秦娥·长飘泊","author":"纳兰性德","dynasty":"清","verses":["长飘泊，多愁多病心情恶。","心情恶。","模糊一片，强分哀乐。","拟将欢笑排离索，镜中无奈颜非昨。","颜非昨。","才华尚浅，因何福薄。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-4","tags":[]},{"id":"poem-aae3b1f62c7093d4d61cba8f","title":"残雪","author":"释居简","dynasty":"宋","verses":["前水花新霁，暾云日未升。","簷声都是雨，笕溜半成冰。","幌冷疑眠月，窗虚罢续灯。","独余林杪塔，犹自隠觚棱。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-42241090-7ae3-4ceb-b0e1-e8de5c39c520","tags":[]},{"id":"poem-ab0f4bb121319c58c2aac82c","title":"太和 寿和","author":"贺知章","dynasty":"唐","verses":["惟以明发，有怀载殷。","乐盈而反，礼顺其禋。","立清以献，荐欲是亲。","於穆不已，裒对斯臻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-cc92ee7f-f8d6-47bb-9efe-f2402a4aa123","tags":[]},{"id":"poem-ab1026159ce767ab7889f698","title":"西江月·雄里内含雌质","author":"张伯端","dynasty":"宋","verses":["雄里内含雌质，负阴抱却阳精。","两般和合药方成。","点化魄纤魂胜。","信道金丹一粒，蛇吞立变龙形。","鸡餐亦乃化鸾鹏。","飞入真阳清境。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-975","tags":[]},{"id":"poem-ab109bef3427b987678c8dbc","title":"诉衷情·东风杨柳欲青青","author":"晏殊","dynasty":"宋","verses":["东风杨柳欲青青。","烟淡雨初晴。","恼他香阁浓睡，撩乱有啼莺。","眉叶细，舞腰轻。","宿妆成。","一春芳意，三月和风，牵系人情。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-493","tags":[]},{"id":"poem-ab11dbbf5e0dcf78da885421","title":"奉济驿重送严公四韵","author":"杜甫","dynasty":"唐","verses":["远送从此别，青山空复情。","几时桮重把，昨夜月同行。","列郡讴歌惜，三朝出入荣。","江村独归处，寂寞养残生。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-c2c83ee2-940f-4ae3-9ab3-4f509d2991f3","tags":["唐诗三百首","送别","五言律诗","惜别"]},{"id":"poem-ab1251cdea9f9d0e97a542ab","title":"苏武慢·雁落平沙","author":"蔡伸","dynasty":"宋","verses":["雁落平沙，烟笼寒水，古垒鸣笳声断。","青山隐隐，败叶萧萧，天际暝鸦零乱。","楼上黄昏，片帆千里归程，年华将晚。","望碧云空暮，佳人何处，梦魂俱远。","忆旧游、邃馆朱扉，小园香径，尚想桃花人面。","书盈锦轴，恨满金徽，难写寸心幽怨。","两地离愁，一尊芳酒，凄凉危阑倚遍。","尽迟留、凭仗西风，吹干泪眼。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-205","tags":["宋词三百首"]},{"id":"poem-ab1a21be20d16168f0be363c","title":"上洛桥","author":"李益","dynasty":"唐","verses":["金谷园中柳，春来似舞腰。","何堪好风景，独上洛阳桥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-40a9fe70-40d2-4718-a1af-09193449508a","tags":[]},{"id":"poem-ab1b2365af8257e711390746","title":"宫词","author":"朱庆余","dynasty":"唐","verses":["寂寂花时闭院门，美人相并立琼轩。","含情欲说宫中事，鹦鹉前头不敢言。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-ab4b1a7f-4fbe-438b-817f-9e1ed2d39f4f","tags":["唐诗三百首","七言绝句","宫怨","写景"]},{"id":"poem-ab3bf7e9ede18c3504589134","title":"秋暮言志","author":"太宗皇帝","dynasty":"唐","verses":["朝光浮烧野，霜华净碧空。","结浪冰初镜，在迳菊方丛。","约岭烟深翠，分旗霞散红。","抽思滋泉侧，飞想傅岩中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-9d2bcfb9-1052-40ca-8a14-87ba811aee4e","tags":[]},{"id":"poem-ab3cbacaadcad44e2affc137","title":"喷玉潭","author":"司马光","dynasty":"宋","verses":["千尺崖头一派清，古今不绝坠峥嵘。","长风卷起散岩壑，此日方知喷玉名。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-0ef2ebe0-bb93-4efd-98ad-26631b396951","tags":[]},{"id":"poem-ab4064058d00c6784b9c1ce4","title":"思贤岩","author":"陈岩","dynasty":"宋","verses":["谏稿成埃两鬓丝，考槃在涧倚天知。","岩前风叶行人耳，便是襄阳堕泪碑。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-7af12fc3-d929-4bc4-bb23-b3d0de0288e1","tags":[]},{"id":"poem-ab4536ee2dc32150b3c1b3c0","title":"西湖晚归  其二","author":"宋伯仁","dynasty":"宋","verses":["风力尖纤酒力微，重添脱下薄绵衣。","心忙愈觉苏堤远，趁得渔船载得归。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-df1afb31-ab3a-40c0-b408-96552e76b4a3","tags":["西湖"]},{"id":"poem-ab558b864977848f7f3a46e4","title":"郊庙歌辞 享太庙乐章 长发舞","author":"魏征、褚亮","dynasty":"唐","verses":["睿哲维唐，长发其祥。","帝命斯祐，王业克昌。","配天载德，就日重光。","本支百代，申锡无疆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-62ac1952-e0f1-4935-8e06-9d8f9f72bb6f","tags":[]},{"id":"poem-ab5c61f8f23248d2f0634036","title":"望远行","author":"施惠《幽闺记》","dynasty":"元","verses":["(生上)春风紫陌，又是大涯行客。","(小生上)野草闲花，掩映水光山色。","(末、净上)杏花朵朵欹红，杨柳丝丝弄碧，沙岸远涟漪初溢。","(生)携书挟策赴天邦，(小生)那更风光直艳阳，(末)路上野花钻地出。","(净)村中美酒透瓶香。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3061","tags":[]},{"id":"poem-ab5db027f912bd9a42d25b3f","title":"答卢虔故园见寄","author":"孟郊","dynasty":"唐","verses":["访旧无一人，独归清雒春。","花闻哭声死，水见别容新。","乱后故乡宅，多为行路尘。","因悲楚左右，谤玉不知珉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-cff74d90-de40-4e9a-a1b8-f3885700f76d","tags":[]},{"id":"poem-ab6178426dd56f101f7a70c3","title":"宿溪僧院","author":"曹松","dynasty":"唐","verses":["少年云溪里，禅心夜更闲。","煎茶留静者，靠月坐苍山。","露白钟寻定，萤多户未关。","嵩阳大石室，何日译经还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-aacd7716-148f-4c14-a986-d5f80b59806d","tags":[]},{"id":"poem-ab680a979178cbf5559a038b","title":"梧叶儿","author":"杨景贤","dynasty":"元","verses":["锡仗金环重，袈裟玉璧偏，两耳似垂肩。","有佛祖心间印，少如来足下莲。","心一似铁石坚，全不避山遥路远。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3390","tags":[]},{"id":"poem-ab6df0f6a67c4a2e1db5a47a","title":"普贤歌","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["身充里正实难当。","杂泛应承日夜忙。","官司点义仓，并无些子粮，拚一个拖番吃大棒。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5036","tags":[]},{"id":"poem-ab6e62d2a3496fcfb81a18dc","title":"早朝","author":"王维","dynasty":"唐","verses":["皎洁明星高，苍茫远天曙。","槐雾暗不开，城鸦鸣稍去。","始闻高阁声，莫辨更衣处。","银烛已成行，金门俨驺驭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-99c56ac4-c95e-4923-b0b8-b3809e62e1cf","tags":[]},{"id":"poem-ab70550354d3d89c7a0e671c","title":"点绛唇·清夜沈沈","author":"王十朋","dynasty":"宋","verses":["清夜沈沈，携来深院柔枝小。","俪兰开巧。","雪里乘风袅。","温室寒祛，旖旎仙姿早。","看成好。","花仙欢笑。","不管年华老。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-573","tags":[]},{"id":"poem-ab780e71368f4f65485aa54a","title":"秋日宿简寂观陆先生草堂","author":"张祜","dynasty":"唐","verses":["紫霄峰下草堂仙，千载空梁石磬悬。","白气夜生龙在水，碧云秋断鹤归天。","竹廊影过中庭月，松槛声来半壁泉。","明日又为浮世恨，满山行路梦依然。","（见《吉石庵丛书》本陈舜俞《庐山记》卷四，题作《简寂观》，「空梁」作「空遗」，「竹廊」作「空遗」，「竹廊」作「竹房」，「銮过」作「影占」，「行路」作「徒积」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-2e9d7727-8434-42c3-9122-978eb79cf2b4","tags":["庐山"]},{"id":"poem-ab7daf6222a7a6e6459c34e0","title":"和白州钱使君上元夜侍宴","author":"徐铉","dynasty":"宋","verses":["御宴宵陈敞百层，君恩芳景两难胜。","风传天上九成乐，月映楼前万树灯。","醉捧玉觞疑梦寐，静临丹槛似飞腾。","因观谢守窗中咏，自愧瀛洲是滥登。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-f875659f-040d-4f80-bf0a-d084a63a88ff","tags":[]},{"id":"poem-ab80726e3672a3ab2d4fab4d","title":"渔父词・渔父·春入渭阳花气多","author":"赵构","dynasty":"宋","verses":["春入渭阳花气多。","春归时节自清和。","冲晓雾，弄沧波。","载与俱归又若何。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-226","tags":[]},{"id":"poem-ab86230378e3b02f9356b5c2","title":"征怨","author":"柳中庸","dynasty":"唐","verses":["岁岁金河复玉关，朝朝马策与刀环。","三春白雪归青冢，万里黄河遶黑山。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-92dd65da-8301-4c83-b8f3-986b6095c481","tags":["唐诗三百首","黄河","边塞","七言绝句"]},{"id":"poem-aba4a9ebe888b9bb09267adf","title":"酹江月・念奴娇·三光五岳","author":"黄宰","dynasty":"宋","verses":["三光五岳，孕乾坤英彩，非金非玉。","赫赫岩岩真相种，来驾横空仙鹄。","十万儿童，和丰堂下，齐指梅山祝。","黑头难老，岁寒苍桧修竹。","须信自家有传，中庸一卷，是长生真箓。","借问洛阳归去后，几度桃开桃熟。","十九年间，梦回天上，再见棠阴绿。","相将促觐，已闻沙路新筑。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-858","tags":[]},{"id":"poem-abaae6c11121b46658812706","title":"观骑射","author":"李益","dynasty":"唐","verses":["边头射雕将，走马出中军。","远见平原上，翻身向暮云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-8aa31994-11ad-4080-8373-81b05d155b6e","tags":[]},{"id":"poem-abad4be9f818a65b69c291d4","title":"惜红衣·鹭老秋丝","author":"吴文英","dynasty":"宋","verses":["鹭老秋丝，苹愁暮雪，鬓那不白。","倒柳移栽，如今暗溪碧。","乌衣细语，伤绊惹、茸红曾约。","南陌。","前度刘郎，寻流花踪迹。","朱楼水侧。","雪面波光，汀莲沁颜色。","当时醉近绣箔，夜吟寂。","三十六矶重到，清梦冷云南北。","买钓舟溪上，应有烟蓑相识。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-501","tags":[]},{"id":"poem-abb1186ac0afe38365312f31","title":"仙源即事  其二","author":"王镃","dynasty":"宋","verses":["避世移家入乱山，松风杉雨打窗寒。","床头一卷麻衣易，自点松明尽夜看。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-46af5910-76bb-4eda-a469-7d1b3cb83db1","tags":[]},{"id":"poem-abb33e531cec8f0724fef0ff","title":"尾声","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(旦)官人且请归房内，叔叔回归下处，待等明朝复探取。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1781","tags":[]},{"id":"poem-abb6fc90a45a389c65b7a29a","title":"鼓吹曲辞 鼓吹铙歌 河右平","author":"柳宗元","dynasty":"唐","verses":["河右澶漫，顽为之魁。","王师如雷震，昆仑以颓。","上聋下聪，骜不可回。","助雠抗有德，惟人之灾。","乃溃乃奋，执缚归厥命。","万室蒙其仁，一夫则病。","濡以鸿泽，皇之圣。","威畏德怀，功以定。","顺之于理，物咸遂厥性。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-e1264668-8b25-4c5a-9260-904b20979589","tags":[]},{"id":"poem-abb8f4f86b7ecb55e6dd0875","title":"谢邢少连送葡萄豆蔻栽  其二","author":"张栻","dynasty":"宋","verses":["留取园中数亩赊，拟栽灵药谢纷华。","儿童今日知翁喜，移得君家豆蔻花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-fdb2e785-30f4-4f7f-abae-c6fb6c6cd296","tags":[]},{"id":"poem-abc0941eace5ed3c06d9bf30","title":"泗州画赞","author":"林之奇","dynasty":"宋","verses":["稽首泗州普照王，曩以宝塔接群品。","塔今败坏成微尘，随意分身无不在。","我观世间有为法，无常迁变同一空。","假饶建塔如恒沙，未有不归幻灭者。","岂惟淮塔有兴废，阿育王造亦非坚。","菩萨应感常现世，不随宝塔俱存亡。","耕雨获晴长淮风，普为众生作饶益。","我今绘此应感象，常以正念为皈依。","于此员光一寻中，而兴七级浮屠想。","正念皈依无间断，普愿菩萨常感通。","洪钟小大随叩鸣，所求所请皆如意。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-97b07f1e-b58f-42fa-8933-80adbab99ae6","tags":[]},{"id":"poem-abc8355959dfa9751263f805","title":"晚眺","author":"孟宾于","dynasty":"宋","verses":["倚杖残秋里，吟中四顾频。","西风天际雁，落日渡头人。","草色衰平野，山阴歛暮尘。","却寻苔径去，明月照村邻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-de424fd1-083e-4f71-8a67-a6bbf8b24c27","tags":[]},{"id":"poem-abd12c67a0d092754c4440bd","title":"寄玉笥山沈道士","author":"徐铉","dynasty":"宋","verses":["珍重江南沈炼师，未曾相识久相思。","已全真气能从俗，不坠家风善赋诗。","玉笥共游知早晚，金貂回顾觉喧卑。","多惭书札遥相问，更望刀圭换白髭。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-1afe3b68-82c0-4e5a-9ad8-273a5892095f","tags":[]},{"id":"poem-abd1bb4df724669d1497414b","title":"别何处士陵俊老","author":"谭用之","dynasty":"宋","verses":["三皇上人春梦醒，东侯老大麒麟生。","洞连龙穴全山冷，窗透鼇波尽室清。","计拙耻居岩麓老，气狂惭与斗牛平。","谁人为向青编上，直傍巢由写一名。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-43a44c6a-b036-419f-9651-01d1af492358","tags":[]},{"id":"poem-abd22a2d66f3ce48a2350af4","title":"思平泉树石杂咏一十首 海上石笋","author":"李德裕","dynasty":"唐","verses":["常爱仙都山，奇峰千仞悬。","迢迢一何迥，不与众山连。","忽逢海峤石，稍慰平生忆。","何以慰我心，亭亭孤且直。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-0a49c386-19d4-4855-ab4d-d357ae71cd38","tags":[]},{"id":"poem-abd60ac40d9a5805d86872b8","title":"太乙宫即事  其二","author":"王同祖","dynasty":"宋","verses":["绿阴密处著危亭，佳气葱葱王武林。","一片红尘飞不入，杜鹃啼处白云深。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-0face657-feeb-4abd-85b7-3077634d4300","tags":[]},{"id":"poem-abd982bf50218fdcc7950c9d","title":"哭陈陶处士","author":"曹松","dynasty":"唐","verses":["园里先生冢，鸟啼春更伤。","空余八封树，尚对一茅堂。","白日埋杜甫，皇天无耒阳。","如何稽古力，报答甚茫茫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-1ef5d938-b410-448e-9349-0592d63d315f","tags":[]},{"id":"poem-abdf89c2bfc9b3e39864d073","title":"和裴少府怀京兄弟","author":"皎然","dynasty":"唐","verses":["宦游三楚外，家在五陵原。","凉夜多归梦，秋风满故园。","北书无远信，西候独伤魂。","空念青门别，殷勤岐路言。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-e438ac36-0098-48c2-9f19-538b3864b9eb","tags":[]},{"id":"poem-abe56b97f81c585d2263d2d7","title":"闻李频员外卒","author":"贯休","dynasty":"唐","verses":["苍苍难可问，问荅亦难闻。","落叶平津岸，愁人李使君。","文章应力竭，茅土始天分。","又逐东风去，迢迢隔岭云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-20ddb6ca-d910-4a35-8f78-f7206e28b12d","tags":[]},{"id":"poem-abefd99ff8e83620d4f96ccb","title":"同李司直题武丘寺兼留诸公与陆羽之无锡","author":"皎然","dynasty":"唐","verses":["陵寝成香阜，禅枝出白杨。","劒池留故事，月树即他方。","应世缘须别，栖心趣不忘。","还将陆居士，晨发泛归航。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-f8a801ae-24da-4893-bc08-9c0b357326cc","tags":[]},{"id":"poem-abf0ea23b8a8f0dcc0466107","title":"老农十首  其六","author":"曾协","dynasty":"宋","verses":["敢将体足惮沾涂，日日高原带雨锄。","乞与丰年酬作苦，也知天意解乘除。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-03a09cb2-9f41-47f9-98fb-c7da7b2b44ce","tags":[]},{"id":"poem-abf4a65e223ea73a1b4485be","title":"送侯山人赴会稽","author":"崔峒","dynasty":"唐","verses":["仙客辞萝月，东来就一官。","且归沧海住，犹向白云看。","猨呌江天暮，虫声野浦寒。","时游镜湖里，为我把鱼竿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-651ebe46-5927-4e46-8cec-68edf7f09fa8","tags":[]},{"id":"poem-abf6cf525fde18e6ee1b71db","title":"赠前蔚州崔使君","author":"马戴","dynasty":"唐","verses":["战回脱剑绾铜鱼，塞鴈迎风避隼旟。","欲识前时为郡政，校成上下考新书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-45213ee8-2745-4f4b-b0d5-d1a0add85c13","tags":[]},{"id":"poem-abf83c31cb698806da2bd13e","title":"秋日金陵制幕书事  其三","author":"王同祖","dynasty":"宋","verses":["哨马纷纷一水间，渡头分戍要防奸。","可怜生计渔舟者，官给旗牌禁往还。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-b6d62407-0a44-464c-9d0b-261a931479de","tags":[]},{"id":"poem-abf8be1fed99782831341eac","title":"杂曲歌辞 行路难三首 一","author":"李白","dynasty":"唐","verses":["金尊清酒斗十千，玉盘珍羞直万钱。","停杯投筯不能食，拔劒四顾心茫然。","欲渡黄河冰塞川，将登太行雪暗天。","闲来垂钓坐溪上，忽复乘舟梦日边。","行路难，行路难，多岐路，今安在？长风破浪会有时，直挂云帆济沧海。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-527eba4b-b35c-4d29-99e7-8f40c6f3d5b7","tags":["黄河","励志","友情","八年级下册(课内)","初中古诗","乐府","唐诗三百首","宴饮","哲理","怀才不遇"]},{"id":"poem-abf9932903bbffc6b5f326b2","title":"奉陪洞霄内阁拉殊师利宿穹窿本公故寺绝类岳麓感之而作","author":"米芾","dynasty":"宋","verses":["湘西衣冷榻留云，此夕还如入梦魂。","六月薜萝嗟我欲，一生林壑与心论。","吴王旧赏今何有，惠可余光宛若存。","对榻深堂清话歇，长风快雨洗松门。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-328c10c4-4e4f-4231-a62a-9df5b8e244a0","tags":[]},{"id":"poem-ac03f6acb199c19b1432e362","title":"书雪巢林景思诗卷","author":"释居简","dynasty":"宋","verses":["诗人巢雪如住山，巢中所得强得官。","官微不足了𫗴粥，尽日幽寻遣儿读。","舂容大篇辄千字，炼字贵活不贵死。","乡来杜陵有布衣，晚到夔州也如此。","乃今遗藁安在哉，古花囊锦宗文开。","开缄宛见谏议面，只字重哦复三咽。","三咽然后耳有闻目有见，见人捧心颦两眉。","不学施家女，只学唐人诗。","为言诸子将安之，巢空雪明康鼎来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-2df38f99-3d10-4523-906e-6f7609fea0fd","tags":[]},{"id":"poem-ac05ce088c319dad099bd524","title":"和定国湖上  其三","author":"刘跂","dynasty":"宋","verses":["菰蒲深处水藏波，邂逅相忘自啸歌。","曳组悬龟知底用，水边消得一渔蓑。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-367d5020-44b6-4149-af2c-a17a4fd75daf","tags":[]},{"id":"poem-ac0c553d849fddea2a6304b9","title":"送汀州源使君","author":"张籍","dynasty":"唐","verses":["曾成赵北归朝计，因拜王门最好官。","为郡暂辞双凤阙，全家远过九龙滩。","山乡祗有输蕉户，水镇应多养鸭栏。","地僻寻常来客少，刺桐花发共谁看。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-109f899b-84f0-4e71-959a-969db7f67755","tags":[]},{"id":"poem-ac129c59160e9647039dc4e4","title":"春思","author":"李白","dynasty":"唐","verses":["燕草如碧丝，秦桑低绿枝。","当君怀归日，是妾断肠时。","春风不相识，何事入罗帏。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-7277c420-9f3f-4093-a5b2-6331494721e8","tags":["唐诗三百首","思念","五言古诗","春天","坚贞","妇女"]},{"id":"poem-ac2f209d9e48c1f1b030687f","title":"狱空行上献府公朝奉麾下涟水令米芾皇恐","author":"米芾","dynasty":"宋","verses":["楚州五邑口百万，扰静尽系太守公。","政由吏人民乃扰，政由太守民气通。","安土乐生善民欲，恶民惟欲与吏同。","太守无能不戢吏，精力不给吏乃庸。","两狱百间塞有罪，有耳未闻一日空。","晋昌唐公名世后，清风素节为时宗。","五更三点运精思，众人安寝吏计穷。","百姓小妄赦不罪，庶几小屈能自致。","五邑来者初亦汇，久而官悚吏皆畏，虽欲呼之亦不至。","乃知狱空空有理，百万无冤无枉吏。","来者迎刃无留滞，赦来两狱久无事。","太守政声既如此，廉车旁午目所备。","胡不剡章上天子，追风早来促公起。","去入省闱或使指，吏皆欲去民欲留。","我祝公去岂同吏，长坂大车程万里。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-cdf18671-710b-4979-a62a-6fa97da51e65","tags":[]},{"id":"poem-ac4871fc56e262dfee6627c3","title":"酒泉子·三月暖风","author":"晏殊","dynasty":"宋","verses":["三月暖风，开却好花无限了，当年丛下落纷纷。","最愁人。","长安多少利名身。","若有一杯香桂酒，莫辞花下醉芳茵。","且留春。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-479","tags":[]},{"id":"poem-ac4b28b94f2140fa373e4417","title":"浣溪沙·绝代佳人淑且真","author":"张孝祥","dynasty":"宋","verses":["绝代佳人淑且真。","雪为肌骨月为神。","烛前花底不胜春。","倚竹袖长寒卷翠，凌波袜小暗生尘。","十分京落旧家人。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-280","tags":[]},{"id":"poem-ac4b7301f1a5699b0c3c98f5","title":"螽斯","author":"佚名","dynasty":"先秦","verses":["螽斯羽，诜诜兮。宜尔子孙，振振兮。","螽斯羽，薨薨兮。宜尔子孙。绳绳兮。","螽斯羽，揖揖兮。宜尔子孙，蛰蛰兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-4","tags":[]},{"id":"poem-ac4fc0a78e2ee06aed448e51","title":"白纻歌二首 二","author":"王建","dynasty":"唐","verses":["馆娃宫中春日暮，荔枝木瓜花满树。","城头乌栖休击鼓，青蛾弹瑟白纻舞。","夜天曈曈不见星，宫中火照西江明。","美人醉起无次第，堕钗遗珮满中庭。","此时但愿可君意，回昼为宵亦不寐，年年奉君君莫弃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-32e0c97c-34f5-4030-bd0a-a410f5643784","tags":[]},{"id":"poem-ac560537926ea7a105a96b84","title":"夏日途中","author":"李廓","dynasty":"唐","verses":["树夹炎风路，行人正午稀。","初蝉数声起，戏蝶一团飞。","日色欺清镜，槐膏点白衣。","无成归故里，自觉少光辉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-239b21ee-29f9-46b1-8530-64b3eb5ea970","tags":[]},{"id":"poem-ac6a408cc47237bc65e45485","title":"清明日登城春望寄大夫使君","author":"王表","dynasty":"唐","verses":["春城闲望爱睛天，何处风光不眼前。","寒食花开千树雪，清明日出万家烟。","兴来促席唯同舍，醉后狂歌尽少年。","闻说莺啼却惆怅，诗成不见谢临川。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-e9ff4727-4dec-4fd8-ab61-336c693af7c3","tags":[]},{"id":"poem-ac6a8c06776cd0e5767d6953","title":"戏题画山水图歌","author":"杜甫","dynasty":"唐","verses":["十日画一水，五日画一石。","能事不受相促迫，王宰始肯留真迹。","壮哉昆仑方壶图，挂君高堂之素壁。","巴陵洞庭日本东，赤岸水与银河通，中有云气随飞龙。","舟人渔子入浦溆，山木尽亚洪涛风。","尤工远势古莫比，咫尺应须论万里。","焉得幷州快剪刀，剪取吴松半江水。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-ae1c6979-d71b-48ab-b50d-9a9a210ec4c9","tags":["洞庭湖","写人","赞美","写人诗"]},{"id":"poem-ac74a88f97ca9be1b7281974","title":"郊庙歌辞 汉宗庙乐舞辞 显仁舞","author":"张昭","dynasty":"唐","verses":["运极金行谢，天资水德隆。","礼神鄜畤馆，布政未央宫。","诘旦备明祀，登歌荅茂功。","云轩临降久，星俎荐陈丰。","霭霭沈檀雾，铿锵环佩风。","荧煌升藻藉，肸蚃转珠栊。","尊祖咸韶备，贻孙书轨同。","京坻长有积，宗社享无穷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-4866e70c-51c9-48bb-a2b4-d4d975e338fe","tags":[]},{"id":"poem-ac7b22f18d257d96bb624c7f","title":"吊卢殷 四","author":"孟郊","dynasty":"唐","verses":["登封草木深，登封道路微。","日月不与光，莓苔空生衣。","可怜无子翁，蚍蜉缘病肌。","挛卧岁时长，涟涟但幽噫。","幽噫虎豹闻，此外相访稀。","至亲唯有诗，抱心死有归。","河南韩先生，后君作因依。","磨一片嵌岩，书千古光辉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-5b282752-b9a3-49c7-b975-1f65993ea72a","tags":[]},{"id":"poem-ac994e3306a911d0bbed18c2","title":"和劝农篇","author":"李纲","dynasty":"宋","verses":["天临下土，是生烝民。","耕食凿饮，乃含其真。","淳浇朴散，巧伪相因。","谁其还之，时惟圣人。","圣人立政，爰重黍稷。","设命官司，职是播植。","春勤于耕，秋乃有穑。","储其嬴余，荒岁足食。","瞻彼中原，祁邳平陆。","春日载阳，和风肃穆。","夫耕妇馌，俦类相逐。","少壮竭力，逸此耆宿。","岂无他图，惟兹永久。","利其耒耜，十千维耦。","带月荷锄，侵星耘亩。","崇本抑末，孰敢游手。","终年厌飧，报则不贵。","千箱万仓，以副汝冀。","为酒为醴，乐此分至。","仰奉俯畜，夫复何愧。","四体不勤，丈人所鄙。","带经而耕，岂废冠履。","我思古人，希风往轨。","躬耕南阳，无使专美。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-723b6ace-edf6-4b51-9857-291c57db377f","tags":[]},{"id":"poem-ac9ad193bb9a5a8b29a5d390","title":"郊庙歌辞 太清宫乐章 序入破第二奏","author":"不详","dynasty":"唐","verses":["虚极仙宗本，希夷象帝先。","百灵朝太上，万法祖重圆。","善贷惟冲德，功成谓自然。","云门达和气，思用合钧天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-fa252fae-6e68-425e-b0b3-89acc657b20c","tags":[]},{"id":"poem-aca2bce99be77d116f7c88a5","title":"思齐","author":"佚名","dynasty":"先秦","verses":["思齐大任，文王之母，思媚周姜，京室之妇。大姒嗣徽音，则百斯男。","惠于宗公，神罔时怨，神罔时恫。刑于寡妻，至于兄弟，以御于家邦。","雍雍在宫，肃肃在庙。不显亦临，无射亦保。","四戎疾不殄，烈假不瑕。不闻亦式，不谏亦入。四成人有德，小子有造。古之人无斁，誉髦斯士。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-239","tags":[]},{"id":"poem-acb4d0b9bdb0d6f9533d1d39","title":"更漏子·今夜期","author":"孙光宪","dynasty":"五代","verses":["今夜期，来日别，相对只堪愁绝。","偎粉面，捻瑶簪，无言泪满襟。","银箭落，霜华薄，墙外晓鸡咿喔。","听咐嘱，恶情悰，断肠西复东。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-22","tags":[]},{"id":"poem-acb5f248b023384ace022694","title":"思越人·燕双飞","author":"张泌","dynasty":"五代","verses":["燕双飞，莺百啭，越波堤下长桥。","斗钿花筐金匣，恰舞衣罗薄纤腰。","东风淡荡慵无力，黛眉愁聚春碧。","满地落花无消息，月明肠断空忆。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-44","tags":[]},{"id":"poem-acb72c50e7568ea096adda94","title":"中秋夜君山台望月","author":"李涉","dynasty":"唐","verses":["大堤花里锦江前，诗酒同游四十年。","不料中秋最明夜，洞庭湖上见当天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-3cf3e7cd-58bb-4359-9c92-a2ae5b29872f","tags":["洞庭湖"]},{"id":"poem-acb73a06d06b378684fe2d3e","title":"兵车行","author":"杜甫","dynasty":"唐","verses":["车辚辚，马萧萧，行人弓箭各在腰。","耶娘妻子走相送，尘埃不见咸阳桥。","牵衣顿足阑道哭，哭声直上干云霄。","道傍过者问行人，行人但云点行频。","或从十五北防河，便至四十西营田。","去时里正与裹头，归来头白还戍边。","边亭流血成海水，武皇开边意未已。","君不闻汉家山东二百州，千村万落生荆杞。","纵有健妇把锄犂，禾生陇亩无东西。","况复秦兵耐苦战，被驱不异犬与鸡。","长者虽有问，役夫敢申恨。","且如今年冬，未休关西卒。","县官急索租，租税从何出？信知生男恶，反是生女好。","生女犹是嫁比邻，生男埋没随百草。","君不见青海头，古来白骨无人收。","新鬼烦冤旧鬼哭，天阴雨湿声啾啾。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-bd57a0b0-28a1-4d53-bc09-51899d2dac38","tags":["唐诗三百首","叙事","战争","忧国忧民","乐府","新乐府辞"]},{"id":"poem-acb7a93401cc164a783085db","title":"经故宅有感","author":"周繇","dynasty":"唐","verses":["身没南荒雨露赊，朱门空锁旧繁华。","池塘凿就方通水，桃杏栽成未见花。","异代图书藏几箧，倾城罗绮散谁家。","昔年埏埴生灵地，今日生人为叹嗟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-e7d21ab1-31ff-4123-a86d-b1fdba206429","tags":[]},{"id":"poem-acb7d948ceef5b96aef16704","title":"兵要望江南 医方第二十九（十六首） 十一","author":"易静","dynasty":"唐","verses":["军或患，发背及痈疽。","人屎粪盘下润土，碾细筛罗贴敷之，猪胆共调施。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-77936bc9-00a0-4cb7-9998-624a6243727f","tags":[]},{"id":"poem-acc75db85b9062d4425f659e","title":"子夜吴歌 春歌","author":"李白","dynasty":"唐","verses":["秦地罗敷女，采桑绿水边。","素手青条上，红妆白日鲜。","蚕饥妾欲去，五马莫留连。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-4e92a96d-aa74-4153-8314-b6df22d1e18a","tags":["唐诗三百首","清商曲辞","春天","女子","乐府","赞美"]},{"id":"poem-acd0667fa685db3ee183923b","title":"冬日书情","author":"佚名","dynasty":"唐","verses":["殊乡寂寞使人悲，异域留连不暇归。","万里山河非旧国，一川戎俗是新知。","寒天落景光阴促，雪海穹庐物色稀。","为客终朝长下泣，谁怜晓夕老容仪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-84c1a0b9-9ed3-469a-9743-7505cd200201","tags":[]},{"id":"poem-acd1d6700e5083d9782cadd5","title":"踏莎行·情似游丝","author":"周紫芝","dynasty":"宋","verses":["情似游丝，人如飞絮。","泪珠阁定空相觑。","一溪烟柳万丝垂，无因系得兰舟住。","雁过斜阳，草迷烟渚。","如今已是愁无数。","明朝且做莫思量，如何过得今宵去。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-273","tags":["宋词三百首"]},{"id":"poem-acd31695deb4d10f60303c40","title":"夜饮枕流次日以诗记陈迹","author":"曾协","dynasty":"宋","verses":["水轩幽会六人同，夜色苍茫蜡炬红。","淅淅好风天似水，纷纷高论气如虹。","罚筹猬起觞无算，醉骨山颓榼屡空。","却坐胡床看月上，对人楼殿有无中。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-8e6fffd9-a6c8-4a04-b557-9bf99fc45ab5","tags":[]},{"id":"poem-acd7f643b309eb7964e6775c","title":"题李员外厅","author":"李山甫","dynasty":"唐","verses":["石砌蛩吟响，草堂人语稀。","道孤思绝唱，年长渐知非。","名利终成患，烟霞亦可依。","高丘松盖古，闲地药苗肥。","猨鸟啼嘉景，牛羊傍晚晖。","幽栖还自得，清啸坐忘机。","爱彼人深处，白云相伴归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-bae339d2-44f7-45d5-8a12-e26198f3a9c1","tags":[]},{"id":"poem-ace33e033569c89532b9958a","title":"执竞","author":"佚名","dynasty":"先秦","verses":["执竞武王，无竞维烈。不显成康，上帝是皇。自彼成康，奄有四方，斤斤其明。","钟鼓喤喤，磬莞将将，降福穰穰。降福简简，威仪反反。既醉既饱，福禄来反。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-273","tags":[]},{"id":"poem-ace9bfa81c5642fac3cfde65","title":"长安道","author":"聂夷中","dynasty":"唐","verses":["此地无驻马，夜中犹走轮。","所以路傍草，少于衣上尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-5237a4cc-a1d5-48a6-9ec3-72a4b400dea0","tags":[]},{"id":"poem-acea2c1b5773045591cd0bf2","title":"奉和秘书元丞杪秋忆终南旧居","author":"李端","dynasty":"唐","verses":["高门有才子，能履古人踪。","白社陶元亮，青云阮仲容。","田园忽归去，车马杳难逢。","废巷临秋水，支颐向暮峰。","行鱼避杨柳，惊鸭触芙蓉。","石窦红泉细，山桥紫菜重。","凤雏终食竹，鹤侣暂巢松。","愿接烟霞赏，羁离计不从。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-03b478b1-bef3-4398-ab4d-02f480749554","tags":[]},{"id":"poem-aceed3919dd2b22a53b95e44","title":"侍郎见贻佳什愈见高怀因次来章辄歌盛美  其二","author":"李昉","dynasty":"宋","verses":["一簇林亭景象幽，葛巾芒屦恣优游。","未饶荣启歌三乐，不学张衡咏四愁。","二品位高犹是忝，九天恩重若为酬。","儒生所得谁如我，岂复咨嗟雪满头。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-965985ad-c4f4-49e6-94df-b97b600ab546","tags":[]},{"id":"poem-acfb6553a7a8e393cdcb178c","title":"秋风二首 二","author":"杜甫","dynasty":"唐","verses":["秋风淅淅吹我衣，东流之外西日微。","天清小城捣练急，石古细路行人稀。","不知明月为谁好，早晚孤帆他夜归。","会将白发倚庭树，故园池台今是非。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-f1177b2a-c00f-4d1a-a8f8-95e33bd6c4f5","tags":[]},{"id":"poem-acfc459ad1b9cf792a48d94b","title":"送人之天台","author":"李洞","dynasty":"唐","verses":["行李一枝藤，云边晓扣冰。","丹经如不谬，白发亦何能。","浅井仙人镜，明珠海客灯。","乃知真隐者，笑就汉廷徴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-d1c3e41d-abbf-493d-857b-1310850859b3","tags":[]},{"id":"poem-ad033b5ad266601dd0a54586","title":"十二时偈 二","author":"文偃","dynasty":"唐","verses":["鸡鸣丑，一岁孙儿大哮吼。","实相圆明不思议，三世法身藏北斗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-835effb9-9a6a-4f0e-8d07-f960cf063f25","tags":[]},{"id":"poem-ad080eedd07e404bd3679597","title":"政黄牛赞","author":"释了惠","dynasty":"宋","verses":["屈膝跨牛腰，山遥水更遥。","有诗吟未就，白鹭下溪桥。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-75defc42-ee10-428a-912f-d356c8ced3c7","tags":[]},{"id":"poem-ad0a369ba7e81d0d11994153","title":"客淮南病","author":"卢仝","dynasty":"唐","verses":["扬州蒸毒似燂汤，客病清枯鬓欲霜。","且喜闭门无俗物，四肢安稳一张床。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-070f7ff7-71cb-4969-b3b5-d138eaaddfed","tags":[]},{"id":"poem-ad101e64bc0bed02f3f84099","title":"偈颂（幷序○序为南岳齐己撰） 八十五","author":"居遁","dynasty":"唐","verses":["柱杖行低道，逢溪澡潄多。","平田偏乐坐，人命可经过。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-fd1df6e4-bf02-4055-b9eb-22d362a20fb8","tags":["衡山"]},{"id":"poem-ad1151fba84cf2901c619536","title":"成名后作","author":"卢肇","dynasty":"唐","verses":["桂在蟾宫不可攀，功成业熟也何难。","今朝折得东归去，共与乡闾年少看。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-3c035017-f98d-4922-9f93-4629cd53d771","tags":[]},{"id":"poem-ad1bf2c06c0bdcb184bd64b0","title":"忆平泉杂咏 忆初暖","author":"李德裕","dynasty":"唐","verses":["今日初春暖，山中事若何。","雪开喧鸟至，澌散跃鱼多。","幽翠生松栝，轻烟起薜萝。","柴扉常昼掩，惟有野人过。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-691e9ad8-895a-4613-95f9-a006846938e6","tags":[]},{"id":"poem-ad1c332f3fb86be78f2287be","title":"山居诗  其四○","author":"释延寿","dynasty":"宋","verses":["遁迹无图匿姓名，万重山后葺茅亭。","随情因事搜新偈，探妙穷微阅古经。","与道交时心绝念，从缘感处物通灵。","应须长远存高节，屹屹乔松老更青。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-e13be8f5-d458-4957-8f20-bfed13df59eb","tags":[]},{"id":"poem-ad23b99c783c630fdb4fb09a","title":"秦州杂诗","author":"杜甫","dynasty":"唐","verses":["凤林戈未息，鱼海路常难。","候火云峰峻，悬军幕井干。","风连西极动，月过北庭寒。","故老思飞将，何时议筑坛。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-秦州雜詩","tags":[]},{"id":"poem-ad2853ef55a6eed1b8bb775e","title":"烂柯石","author":"孟郊","dynasty":"唐","verses":["仙界一日内，人间千载穷。","双碁未徧局，万物皆为空。","樵客返归路，斧柯烂从风。","唯余石桥在，犹自凌丹虹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-9f003b53-2c93-459b-85f9-01f80a427980","tags":[]},{"id":"poem-ad2a2ae2f09b8e7ba956060e","title":"合源溪期张计不至","author":"李益","dynasty":"唐","verses":["霜露肃时序，缅然方独寻。","暗溪迟仙侣，寒涧闻松禽。","寂历兹夜永，清明秋序深。","微波澹澄夕，烟景含虚林。","素志久沦否，幽怀方自吟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-0412e81a-6c61-423a-9822-8c728327f315","tags":[]},{"id":"poem-ad3113d168113e4f2fba4b96","title":"中吕/粉蝶儿","author":"杨景贤","dynasty":"元","verses":["满腹离愁，诉苍天不能答救，俺一家儿和你有甚冤仇？淹杀我儿夫，奸淫他媳妇，又待废他亲生的骨肉。","那贼汉劣心肠火上浇油，不依从恐遭毒手。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-7947","tags":[]},{"id":"poem-ad3fe9bfb3f0cc5621f740b3","title":"无衣","author":"佚名","dynasty":"先秦","verses":["岂曰无衣？与子同袍。王于兴师，修我戈矛。与子同仇！","岂曰无衣？与子同泽。王于兴师，修我矛戟。与子偕作！","岂曰无衣？与子同裳。王于兴师，修我甲兵。与子偕行！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-132","tags":[]},{"id":"poem-ad41ab3de52fd681887cb809","title":"故行宫","author":"王建","dynasty":"唐","verses":["寥落古行宫，宫花寂寞红。","白头宫女在，闲坐说玄宗。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-a6c85d29-ad02-4f54-a347-63800213a7b4","tags":["唐诗三百首","隋・唐・五代","怀古","宫怨","五言绝句"]},{"id":"poem-ad42caf7f62fc8f399765f59","title":"太常引·玉肌轻衬碧霞衣","author":"高观国","dynasty":"宋","verses":["玉肌轻衬碧霞衣。","似争驾、翠鸾飞。","羞问武陵溪，笑女伴、东风醉时。","不飘红雨，不贪青子，冷澹却相宜。","春晚涌金池，问一片、将愁寄谁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-414","tags":[]},{"id":"poem-ad4777196dc6897acdc6c3da","title":"悲李拾遗二首 一","author":"崔道融","dynasty":"唐","verses":["故友从来匪石心，谏多难得主恩深。","行朝半夜烟尘起，晓殿吁嗟一镜沈。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-a3ba3aaa-56fb-4349-8f6c-993e59c02f11","tags":[]},{"id":"poem-ad4a914d85b1b3994a21da48","title":"浣溪沙·郊游联句","author":"纳兰性德","dynasty":"清","verses":["出郭寻春春已阑(陈维崧)，东风吹面不成寒(秦松龄)，青村几曲到西山(严绳孙)。","并马未须愁路远(姜宸英)，看花且莫放杯闲(朱彝尊)，人生别易会常难(纳兰性德)。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-9","tags":[]},{"id":"poem-ad4c45746bc493c3a0d78e8a","title":"如梦令·厮守许多时价","author":"向","dynasty":"宋","verses":["厮守许多时价。","谁信一筹不画。","相送到矾园，赢得泪珠如泻。","挥洒。","挥洒。","将底江州司马。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-216","tags":[]},{"id":"poem-ad4e999f2ebaaab075fa6bed","title":"奉和九月九日登慈恩寺浮图应制","author":"李迥秀","dynasty":"唐","verses":["沙界人王塔，金绳梵帝游。","言从[祇]树赏，行玩菊丛秋。","御酒调甘露，天花拂彩旒。","尧年将佛日，同此庆时休。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-76c68224-117d-4b08-8a6a-1f4fe60998e1","tags":[]},{"id":"poem-ad549809cb91207ca5602b94","title":"投滑州卢尚书","author":"张祜","dynasty":"唐","verses":["海内诸侯最屈名，不妨中立自经营。","文翁莫猒分符久，韩信终须仗钺行。","静以军威齐虎士，别将才力诮儒生。","亲笔几话南迁客，未必无忧是早荣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-032ad1bb-1476-4794-ade1-952b3e4d8295","tags":[]},{"id":"poem-ad6423403a9dee9c4bf1f167","title":"临江仙·烟收湘渚秋江静","author":"张泌","dynasty":"五代","verses":["烟收湘渚秋江静，蕉花露泣愁红。","五云双鹤去无踪，几回魂断，凝望向长空。","翠竹暗留珠泪怨，闲调宝瑟波中，花鬟月鬓绿云重。","古祠深殿，香冷雨和风。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-37","tags":[]},{"id":"poem-ad67f86f1527da62e7cd2c06","title":"满庭芳·月洗高梧","author":"张","dynasty":"宋","verses":["月洗高梧，露幽草，宝钗楼外秋深。","土花沿翠，萤火坠墙阴。","静听寒声断续，微韵转、凄咽悲沈。","争求侣，殷勤劝织，促破晓机心。","儿时，曾记得，呼灯灌穴，敛步随音。","任满身花影，犹自追寻。","携向花堂戏斗，亭台小、笼巧妆金。","今休说，从渠床下，凉夜伴孤吟。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-190","tags":["宋词三百首"]},{"id":"poem-ad72c2d2793cd57b869f4b6e","title":"女冠子·碧桃红杏","author":"毛熙震","dynasty":"五代","verses":["碧桃红杏，迟日媚笼光影，彩霞深。","香暖熏莺语，风清引鹤音。","翠鬟冠玉叶，霓袖捧瑶琴。","应共吹箫侣，暗相寻。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-44","tags":[]},{"id":"poem-ad748b527681cc7ce5034f3e","title":"送何兆下第还蜀","author":"李端","dynasty":"唐","verses":["重江不可涉，孤客莫晨装。","高木莎城小，残星栈道长。","褭猿枫子落，过雨荔枝香。","劝尔成都住，文翁有草堂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-c0c804f0-03cb-4610-a809-f413608ac25e","tags":[]},{"id":"poem-ad7bc9e496a80c2d3c3f7413","title":"重阳四首 一","author":"司空图","dynasty":"唐","verses":["簷前减燕菊添芳，燕尽庭前菊又荒。","老大比他年少少，每逢佳节更悲凉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-65e1906b-36f6-4a7b-9bfc-82255323a2a4","tags":[]},{"id":"poem-ad7f9dd29f417dfce697e869","title":"答张文成","author":"张𬸦","dynasty":"唐","verses":["（案以下各诗，《游仙窟》虽谓崔十娘所作，要皆张文成戏墨耳。","）面非他舍面，心是自家心。","何处关天事，辛苦漫追寻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c92dba26-eb50-46d1-9a8c-df167168ba33","tags":[]},{"id":"poem-ad82572aab29fefba72e1cba","title":"观壁卢九想图","author":"包佶","dynasty":"唐","verses":["一世荣枯无异同，百年哀乐又归空。","夜阑鸟鹊相争处，林下真僧在定中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-5b59b031-7cee-4c88-8023-1b0b04a9da60","tags":[]},{"id":"poem-ad972c364b61882d8251844f","title":"摸鱼儿·怎知他、春归何处","author":"刘辰翁","dynasty":"宋","verses":["怎知他、春归何处，相逢且尽尊酒。","少年袅袅天涯恨，长结西湖烟柳。","休回首。","但细雨断桥，憔悴人归后。","东风似旧。","问前度桃花，刘郎能记，花复认郎否。","君且住，草草留君翦韭。","前宵更恁时候。","深杯欲共歌声滑，翻湿春衫半袖。","空眉皱。","看白发尊前，已似人人有。","临分把手。","叹一笑论文，清狂顾曲，此会几时又。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-92","tags":["宋词三百首","西湖"]},{"id":"poem-ada17bef3b1f4482a00e5c61","title":"点绛唇·绣岭横秋","author":"毛滂","dynasty":"宋","verses":["绣岭横秋，玉螭吹暑迎凉气。","碧崖流水。","流入春葱指。","半倚朱弦，微亸连环珥。","通深意。","月明风细。","分付知音耳。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-855","tags":[]},{"id":"poem-ada996dda8fda57f679b473c","title":"南乡子·拢云髻","author":"李珣","dynasty":"五代","verses":["拢云髻，背犀梳，焦红衫映绿罗裙。","越王台下春风暖，药盈岸，游赏每邀邻女伴。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-33","tags":[]},{"id":"poem-adaa903fde5ce194cfb4af99","title":"依韵赠南安方处士五首 三","author":"徐夤","dynasty":"唐","verses":["百万僧中不为僧，比君知道仅谁能。","无家寄泊南安县，六月门前也似冰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-89d7ccef-4f26-4b71-97c7-4eb4ef83579c","tags":[]},{"id":"poem-adc240c42a86344fc6978ed2","title":"九歌·礼魂","author":"屈原","dynasty":"先秦","verses":["成礼兮会鼓，传芭兮代舞。","姱女倡兮容与。","春兰兮秋菊，长无绝兮终古。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-11","tags":[]},{"id":"poem-adc3278e32b6bf778ad4ae92","title":"新楼诗二十首 海榴亭","author":"李绅","dynasty":"唐","verses":["海榴亭早开繁蘂，光照晴霞破碧烟。","高近紫霄疑菡萏，迥依江月半婵娟。","怀芳不作翻风艳，别萼犹含泣露妍。","摇落旧丛云水隔，不堪行坐数流年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-8648c94f-3480-4c25-b696-87426376b250","tags":[]},{"id":"poem-adcece87b15367ccfac8f85a","title":"冬晚对雪忆胡居士家","author":"王维","dynasty":"唐","verses":["寒更传晓箭，清镜览衰颜。","隔牖风惊竹，开门雪满山。","洒空深巷静，积素广庭闲。","借问袁安舍，翛然尚闭关。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-6e4d001d-ec19-4bef-886b-a49267ec88c8","tags":["思念","写雪","冬天","雪"]},{"id":"poem-add18324f99e0ed6bbacb9b7","title":"游丝","author":"张栻","dynasty":"宋","verses":["游丝浩荡醉春光，倚頼微风故故长。","几度鶑声留欲住，又随飞絮过东墙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-a6471de1-a338-4feb-aaaa-af4cc6ee0243","tags":[]},{"id":"poem-add867e118122772d82278af","title":"奉和圣制瑞雪篇","author":"刘庭琦","dynasty":"唐","verses":["紫宸飞雪晓裴回，层阁重门雪照开。","九衢皛耀浮埃尽，千品差池贽帛来。","何处田中非种玉，谁家院里不生梅？","埋云翳景无穷已，因风落地吹还起。","先过翡翠宝房中，转入鸳鸯金殿里。","美人含笑出联翩，艳逸相轻鬬容止。","罗衣点著浑是花，玉手抟来半成水。","奕奕纷纷何所如，顿忆杨园二月初。","羞同班女高秋扇，欲照明王乙夜书。","姑射山中符圣寿，芙蓉阙下降神车。","愿随睿泽流无限，长报丰年贵有余。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-6f234307-50b8-4f01-8dfe-fba9acd9cc7a","tags":[]},{"id":"poem-add8eb295f349b74770ab2cf","title":"秋末寄张侍郎","author":"贯休","dynasty":"唐","verses":["静坐黔城北，离仁半岁彊。","雾中红黍熟，烧后白云香。","多病如何好，无心去始长。","寂寥还得句，溪上寄三张。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-3dc3720c-f1fc-4a11-8cc6-097cfe626633","tags":[]},{"id":"poem-addb3c1781ed5882705d0a3d","title":"蕉叶","author":"徐夤","dynasty":"唐","verses":["绿绮新裁织女机，摆风摇日影离披。","只应青帝行春罢，闲倚东墙卓翠旗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-17483666-0c00-4a97-9824-4ee04d4ca776","tags":[]},{"id":"poem-addf7612fc75eff80dfc7e22","title":"双泉","author":"陈岩","dynasty":"宋","verses":["槛泉涌出不多深，兑泽相资互有心。","水净苦嫌尘土污，底须吾欲濯吾襟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-fb921263-8e63-477a-99c0-9f5ceecf558d","tags":[]},{"id":"poem-ade25ad8be47347fa1cdeeb7","title":"五十","author":"王梵志","dynasty":"唐","verses":["有德之（一本作「人」。","）心下，无才意即高。","但看行滥物，若个是坚（郑本作「坚」。","）牢。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-f0d92d10-3ccb-4ef8-ac41-f930597c521e","tags":[]},{"id":"poem-ade5e8465c939163df4fd24a","title":"九章·思美人","author":"屈原","dynasty":"先秦","verses":["思美人兮，揽涕而竚眙。","媒绝路阻兮，言不可结而诒。","蹇蹇之烦冤兮，陷滞而不发。","申旦以舒中情兮，志沉菀而莫达。","愿寄言于浮云兮，遇丰隆而不将。","因归鸟而致辞兮，羌迅高而难当。","高辛之灵盛兮，遭玄鸟而致诒。","欲变节以从俗兮，媿易初而屈志。","独历年而离愍兮，羌凭心犹未化。","宁隐闵而寿考兮，何变易之可为！","知前辙之不遂兮，未改此度。","车既覆而马颠兮，蹇独怀此异路。","勒骐骥而更驾兮，造父为我操之，迁逡次而勿驱兮，聊假日以须是时。","指嶓冢之西隈兮，与𫄸黄以为期。","开春发岁兮，白日出之悠悠。","吾将荡志而愉乐兮，遵江夏以娱忧。","揽大薄之芳茝兮，搴长洲之宿莽。","惜吾不及古人兮，吾谁与玩此芳草？","解萹薄与杂菜兮，备以为交佩。","佩缤纷以缭转兮，遂萎绝而离异。","吾且儃徊以娱忧兮，观南人之变态。","窃快在中心兮，扬厥凭而不竢。","芳与泽其杂糅兮，羌芳华自中出。","纷郁郁其远蒸兮，满内而外扬。","情与质信可保兮，羌居蔽而闻章。","令薜荔以为理兮，惮举趾而缘木。","因芙蓉而为媒兮，惮褰裳而濡足。","登高吾不说兮，入下吾不能。","固朕形之不服兮，然容与而狐疑。","广遂前画兮，未改此度也。","命则处幽吾将罢兮，愿及白日之未暮也。","独茕茕而南行兮，思彭咸之故也。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-18","tags":[]},{"id":"poem-adebc25bcb1bdf34fe26f88c","title":"玲珑四犯·水外轻阴","author":"高观国","dynasty":"宋","verses":["水外轻阴，做弄得飞云，吹断晴絮。","驻马桥西，还系旧时芳树。","不见翠陌寻春，每问著、小桃无语。","恨燕莺、不识闲情，却隔乱红飞去。","少年曾识春风意，到如今、怨怀难诉。","魂惊冉冉江南远，烟草愁如许。","此意待写翠笺，奈断肠、都无新句。","问甚时、舞凤歌鸾，花里再看仙侣。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-385","tags":[]},{"id":"poem-adf9c650c7a0b00491e13aac","title":"江儿水","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(老旦)听说罢衷肠喜只为伊，却元来不从招赘生奸计，恼恨娘行生恶意，凌逼你奸没存济。","母子虔诚遥祭来，望鉴微忱，早赐灵魂来至。","看酒来。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8272","tags":[]},{"id":"poem-adfa9beed277463cb1b97fee","title":"奉酬仲微见寄之作","author":"米芾","dynasty":"宋","verses":["倦游湖海老侵寻，去就何情适契心。","一境山林资我懒，半年风月为君吟。","辟开暗室成三果，选出香峦敌万金。","千里寄声怀惠好，西风正隔洞庭深。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-326dbe3d-429b-4f9e-b30a-e4b4e0134ca3","tags":["洞庭湖"]},{"id":"poem-ae03feba21c501a1451fd4d5","title":"煨芋","author":"李纲","dynasty":"宋","verses":["禅房夜坐腹半饥，寒炉拨火煨蹲鸱。","冻肤傍煖渐舒畅，展转更觉鸣声悲。","毳衣脱落丰肌滑，玉软酥香不劳啮。","芳甘著颊自生津，多病文园正消渇。","吾生老矣来荆蛮，得汝聊助癯儒餐。","不学当年鬼谷子，粪土堆头拜懒残。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-900f0419-b935-4ca0-aa39-55e56daa26c7","tags":[]},{"id":"poem-ae08126411a356d6f55fab5e","title":"青海卧疾之作 二","author":"佚名","dynasty":"唐","verses":["邂逅遇迍蒙，人情讵见通？","昔时曾虎步，即日似禽笼。","有命如朝露，天依类断蓬。","缅怀知我者，荣辱杳难同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-6d4d45e4-c86a-43ff-b8dc-c8245cc70fd0","tags":[]},{"id":"poem-ae08d1a453d9c78be4393edf","title":"郊庙歌辞 享章怀太子庙乐章 迎俎酌献","author":"不详","dynasty":"唐","verses":["通三锡胤，明两承英。","太山比赫，伊水闻笙。","宗祧是寄，礼乐其亨。","嘉辰荐俎，以发声明。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-b94c383f-7e56-4f31-97d9-f5e0b11f6bec","tags":[]},{"id":"poem-ae0b479021cac92540abe303","title":"东风第一枝·巧沁兰心","author":"史达祖","dynasty":"宋","verses":["巧沁兰心，偷黏草甲，东风欲障新暖。","谩凝碧瓦难留，信知暮寒轻浅。","行天入镜，做弄出、轻松纤软。","料故园、不卷重帘，误了乍来双燕。","青未了、柳回白眼。","红欲断、杏开素面。","旧游忆著山阴，厚盟遂妨上苑。","寒炉重暖，便放慢春衫针线。","恐凤靴、挑菜归来，万一灞桥相见。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-180","tags":["宋词三百首"]},{"id":"poem-ae0fd64ba299c78dbd7e09f5","title":"送高适弟耽归临淮作","author":"王维","dynasty":"唐","verses":["少年客淮泗，落魄居下邳。","遨游向燕赵，结客过临淄。","山东诸侯国，迎送纷交驰。","自尔厌游侠，闭户方垂帷。","深明戴家礼，颇学毛公诗。","备知轻济道，高卧陶唐时。","圣主诏天下，贤人不得遗。","公吏奉𫄸组，安车去茅茨。","君王苍龙阙，九门十二逵。","群公朝谒罢，冠劒下丹墀。","野鹤终踉跄，威凤徒参差。","或问理人术，但致还山词。","天书降北阙，赐帛归东菑。","都门谢亲故，行路日逶迟。","孤帆万里外，淼漫将何之。","江天海陵郡，云日淮南祠。","杳冥沧洲上，荡漭无人知。","纬萧或卖药，出处安能期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-e791098d-353d-4ae7-abb4-f632f596eacf","tags":[]},{"id":"poem-ae10c344c91dea3925580128","title":"歌者十二首 十二","author":"司空图","dynasty":"唐","verses":["鹤氅花香搭槿篱，枕前蛩迸酒醒时。","夕阳似照陶家菊，黄蝶无穷压故枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-a6caaaef-0e8a-4c79-bafe-df9e1e8dfa0a","tags":[]},{"id":"poem-ae12ba8cf515e3300d1376ba","title":"题南岳山七言（直在江南）","author":"李存勗","dynasty":"唐","verses":["融峰绝顶九霄边，独立孤峦势近天。","北眺洞庭千里浪，南观石{石禀}万坡烟。","云藏碧涧泉声远，僧迫金乌耳伴喧。","唯有此山侵上界，姮娥吹瑟古松前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-a34be74a-6063-454f-85e1-61826724f40b","tags":["衡山","洞庭湖"]},{"id":"poem-ae18e2011cb665dc8fc755a1","title":"补和王深甫颍川西湖四篇 宜远桥","author":"苏颂","dynasty":"宋","verses":["溪流去无穷，路远更难尽。","信步到桥边，望中千里近。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-64dba1aa-f54d-4e01-a75c-d191c377f6e0","tags":["西湖"]},{"id":"poem-ae24b8cb925275ed7e8c62a7","title":"罗汉岭上古杉","author":"释居简","dynasty":"宋","verses":["一亩蔽苍苔，昙猷手自栽。","滴高零露馥，蟠厚烈风哀。","黛色垂云黑，丹心阅世灰。","儿孙几度老，独立暝云隈。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-cb73b3f4-353d-4d28-920c-82e190d603f0","tags":[]},{"id":"poem-ae25dc2ddd30ac88b84f13fb","title":"浣溪沙·落絮残莺半日天","author":"欧阳炯","dynasty":"五代","verses":["落絮残莺半日天，玉柔花醉只思眠，惹窗映竹满炉烟。","独掩画屏愁不语，斜掩瑶枕髻鬟偏，此时心在阿谁边。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-44","tags":[]},{"id":"poem-ae2c7d586ede4f9c383ffc19","title":"老去也","author":"薛逢","dynasty":"唐","verses":["惆怅人生不满百，一事无成头雪白。","回看幼累与老妻，俱是途中远行客。","匣中旧镜照胆明，昔曾见我髭未生。","朝巾暮栉不自省，老皮皴皱文纵横。","合掌髻子蒜许大，此日方知非是我。","暗数七旬能几何，不觉中肠热如火。","老去也，争奈何，敲酒盏，唱短歌。","短歌未竟日已没，月映西南庭树柯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b56332c5-ea25-4e78-8f08-489da70fb0df","tags":[]},{"id":"poem-ae2f967b0018c0c7a1b39117","title":"听蜀僧濬弹琴","author":"李白","dynasty":"唐","verses":["蜀僧抱绿绮，西下峨眉峰。","为我一挥手，如听万壑松。","客心洗流水，余响入霜钟。","不觉碧山暮，秋云暗几重。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-71999aa1-55dd-4449-81b0-41f04686bf2e","tags":["唐诗三百首","音乐","五言律诗"]},{"id":"poem-ae324d00816c9d3d6ba7cc10","title":"酒泉子·罗带缕金","author":"顾敻","dynasty":"五代","verses":["罗带缕金，兰麝烟凝魂断。","画屏欹，云鬓乱，恨难任。","几回垂泪滴鸳衾，薄情何处去。","月临窗，花满树，信沉沉。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-9","tags":[]},{"id":"poem-ae330ad8da41b80095c702d6","title":"陈几叟以了翁所作默堂箴见示且求余言拾其遗意作四绝句  其一","author":"李纲","dynasty":"宋","verses":["维摩不二门中法，周庙三缄膺上铭。","莫道寂然无所说，须知渊默有雷霆。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-6d0ba7a6-b809-4d16-9ce2-84082883cb04","tags":[]},{"id":"poem-ae343ec101af0f06bd2f6c0d","title":"南乡子·烟暖雨初收","author":"纳兰性德","dynasty":"清","verses":["烟暖雨初收，落尽繁花小院幽。","摘得一双红豆子，低头，说著分携泪暗流。","人去似春休，卮酒曾将酹石尤。","别自有人桃叶渡，扁舟，一种烟波各自愁。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-116","tags":[]},{"id":"poem-ae546d453b67c4d73950d05b","title":"送重表姪王砅评事使南海","author":"杜甫","dynasty":"唐","verses":["我之曾祖姑，尔之高祖母。","尔祖未显时，归为尚书妇。","隋朝大业末，房杜俱交友长者来在门，荒年自糊口。","家贫无供给，客位但箕帚。","俄顷羞颇珍，寂寥人散后。","入怪鬓发空，吁嗟为之久。","自陈剪髻鬟，鬻市充杯酒。","上云天下乱，宜与英俊厚。","向窃窥数公，经纶亦俱有。","次问最少年，虬髯十八九。","子等成大名，皆因此人手。","下云风云合，龙虎一吟吼。","愿展丈夫雄，得辞儿女丑。","秦王时在坐，真气惊户牖。","及乎贞观初，尚书践台斗。","夫人常肩舆，上殿称万寿。","六宫师柔顺，法则化妃后。","至尊均嫂叔，盛事垂不朽。","凤雏无凡毛，五色非尔曹。","往者胡作逆，乾坤沸嗷嗷。","吾客左冯翊，尔家同遁逃。","争夺至徒步，块独委蓬蒿。","逗留热尔肠，十里却呼号。","自下所骑马，右持腰间刀。","左牵紫游缰，飞走使我高。","苟活到今日，寸心铭佩牢。","乱离又聚散，宿昔恨滔滔。","水花笑白首，春草随青袍。","廷评近要津，节制收英髦。","北驱汉阳传，南泛上泷舠。","家声肯坠地，利器当秋毫。","番禺亲贤领，筹运神功操。","大夫出卢宋，宝贝休脂膏。","洞主降接武，海胡舶千艘。","我欲就丹砂，跋涉觉身劳。","安能陷粪土，有志乘鲸鼇。","或骖鸾腾天，聊作鹤鸣臯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d375e62b-149d-4aae-ac75-eb0457e9b7e0","tags":[]},{"id":"poem-ae557ad2c1acb9ee6d52dac7","title":"送韩十四被鲁王推递往济南府","author":"崔国辅","dynasty":"唐","verses":["西候情何极，南冠怨有余。","梁王虽好事，不察狱中书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-c034f0a0-07a1-4254-a4ae-b7411adad5a8","tags":[]},{"id":"poem-ae55e3acaca0e8bf3f36a82f","title":"贺昭国从叔员外转本曹郎中","author":"李洞","dynasty":"唐","verses":["苔砌塔阴浓，朝回尚叫蛬。","粟徴山县欠，官转水曹重。","灯照楼中雨，书求海上峰。","诗家无骤显，一一古人踪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8cd02cdc-e770-4791-ba47-6c81e32d600e","tags":[]},{"id":"poem-ae566fd9c458d784ab27df79","title":"中秋月","author":"裴说","dynasty":"唐","verses":["一岁几盈亏，当轩重此期。","幸无偏照处，刚有不明时。","色静云归早，光寒鹤睡迟。","相看吟未足，皎皎下疎篱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-71080d30-4dd4-4b3b-a73c-d4308bc0b956","tags":[]},{"id":"poem-ae57f272bb352683ca5a1dbf","title":"岐王山亭","author":"张谔","dynasty":"唐","verses":["王家傍绿池，春色正相宜。","岂有楼台好，兼看草树奇。","石榴天上叶，椰子日南枝。","出入千门里，年年乐未移。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-eda88b0f-c62a-45ef-84f5-f60e86a5bc28","tags":[]},{"id":"poem-ae5bd4b820b841a42fa0dcba","title":"客自江南话过亡友朱司议故宅","author":"包佶","dynasty":"唐","verses":["交臂多相共，风流忆此人。","海翻移里巷，书蠹积埃尘。","奉佛栖禅久，辞官上疏频。","故来分半宅，惟是旧交亲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-3b39dc82-798d-44db-8452-bf8e17e7d343","tags":[]},{"id":"poem-ae614b5ba10284e4257aee30","title":"次韵三弟学士题七宝英师壁","author":"苏颂","dynasty":"宋","verses":["岩居得幽胜，俗累无忧伤。","占彼凤山腋，建兹法云堂。","宵眠一毡蒲，昼食几稻粱。","浄众集善缘，勇猛能自强。","瑞相严中楹，梵夹罗四旁。","轩窗据苍崖，松竹围重冈。","不杂人世喧，更觉禅味长。","我尝命宾友，间或携肴觞。","中休憩丈室，远览登上方。","念昔保城堑，屹然壮金汤。","列刹以百数，息民殄千殃。","爰居尽乐土，利用无缺斨。","遂使吴会俗，长为礼义乡。","何独竺乾域，宝山亦清凉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-84c6d394-11fd-4100-9f9a-97193b79686a","tags":[]},{"id":"poem-ae620cc2c8b29edb23e8a57b","title":"春秋战国门 公叔","author":"周昙","dynasty":"唐","verses":["吴起南奔魏国荒，必听公叔失贤良。","无谋纵欲离安邑，可免河沟徙大梁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-3a6729a2-c9bc-45a7-a5a2-e324edba4346","tags":[]},{"id":"poem-ae63c18cbe25366725f7d530","title":"存目  其二","author":"扈蒙","dynasty":"宋","verses":["（以上刘瑛整理）。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-6fa1b3b5-cc7d-404b-9add-9dd532653cb7","tags":[]},{"id":"poem-ae6460e267ef0894470be7f4","title":"赠张𣸣榜头被駮落","author":"赵嘏","dynasty":"唐","verses":["莫向花前泣酒杯，谪仙依旧是仙才。","犹堪与世为祥瑞，曾到蓬山顶上来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-a24d8a04-59dd-4729-820d-2553759d1ccd","tags":[]},{"id":"poem-ae6c5ceb4a0dbb8f9b10debb","title":"懒画眉","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["强对南熏奏虞弦，只见指下余音不似前，那些个流水共高山？呀！怎的只见满眼风波恶，似离别当年怀水仙。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5086","tags":[]},{"id":"poem-ae724ec22cc310b4e0000e55","title":"留题凝翠阁二绝  其二","author":"李纲","dynasty":"宋","verses":["山秀波平望不穷，此身浑堕翠光中。","兵戈满眼栖何地，注目溪头群玉峰。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-49812cfb-b598-4dee-bd00-aced4be06a66","tags":[]},{"id":"poem-ae859fc2917773ca254b2a20","title":"鹊桥仙·远公连社","author":"张抡","dynasty":"宋","verses":["远公连社，流传图画，千古声名独在。","后人多少继遗踪，到我便、失惊打怪。","西方未到，官方先到，冤我白衣吃菜。","龙华三会愿相逢，怎敢学、他家二会。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-993","tags":[]},{"id":"poem-ae8716c678d0372155a7b11c","title":"双髻禅庵请","author":"释原妙","dynasty":"宋","verses":["恣无明，逞人我。","诽释迦，骂达磨。","虽是赤心，返成话堕。","六年坐铺卖不行，至今被人唤作滞货。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-a9e2e58f-88e9-4434-abb9-74e0043de5a9","tags":[]},{"id":"poem-ae938df6cd37ecaed12edfda","title":"寄栖一上人","author":"贯休","dynasty":"唐","verses":["花堑接沧洲，阴云闲楚丘。","雨声虽到夜，吟味不如秋。","古屋藏花鸽，荒园聚乱流。","无机心便是，何用话归休。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-0339c075-3dce-4d7d-8854-c9de165977ca","tags":[]},{"id":"poem-ae940336e8d0f81153eac137","title":"女冠子·双飞双舞","author":"牛峤","dynasty":"五代","verses":["双飞双舞，春昼后园莺语。卷罗帷。","锦字书封了，银河雁过迟。","鸳鸯排宝帐，豆蔻绣连枝。","不语匀珠泪，落花时。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-3","tags":[]},{"id":"poem-ae9ba1cdaa47f4ff14488ade","title":"导引·重华天子","author":"洪适","dynasty":"宋","verses":["重华天子，长至奉神虞。","九奏会轩朱。","星晖云润东方晓，拜贶竹宫初。","归来千乘护皇舆。","瑞景集金铺。","鸡竿高唱恩书下，惠露匝中区。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-777","tags":[]},{"id":"poem-ae9e9849686ee2701520ee44","title":"金陵览古 石头城","author":"朱存","dynasty":"宋","verses":["五城楼雉各相望，山水英灵宅帝王。","此地定由天造险，古来长恃作金汤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-69cf5a0e-55c2-41ee-8bb8-812ce5637d84","tags":[]},{"id":"poem-aeadc59978c44c1cc9291219","title":"勉爱行二首送小季之庐山 二","author":"李贺","dynasty":"唐","verses":["别柳当马头，官槐如兔目。","欲将千里别，持我易斗粟。","南云北云空脉断，灵台经络悬春线。","青轩树转月满床，下国饥儿梦中见。","维尔之昆二十余，年来持镜颇有须。","辞家三载今如此，索米王门一事无。","荒沟古水光如刀，庭南拱柳生蛴螬。","江干幼客真可念，郊原晚吹悲号号。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-b724197b-7e08-48dc-ae31-73b45d05f7ba","tags":["庐山","离别","不舍","愁绪"]},{"id":"poem-aeaf0878cb80fba7fc01d55e","title":"杏殇 一","author":"孟郊","dynasty":"唐","verses":["冻手莫弄珠，弄珠珠易飞。","惊霜莫翦春，翦春无光辉。","零落小花乳，斓斑昔婴衣。","拾之不盈把，日暮空悲归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-b7fe7bae-cf4a-484f-a5c3-726e217a15ce","tags":[]},{"id":"poem-aeb21eaeadd0cb047fa99c48","title":"夜宴安乐公主宅","author":"武平一","dynasty":"唐","verses":["王孙帝女下仙台，金牓珠帘入夜开。","遽惜琼筵欢正洽，唯愁银箭晓相催。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-c8fe718c-a86b-43c0-9e05-944b70c54c57","tags":[]},{"id":"poem-aeb5cf6419f8d24dc92f0df2","title":"秾华","author":"赵崇嶓","dynasty":"宋","verses":["秾华侈春艳，松柏凌霜雪。","芳时若转盼，万族畏销歇。","人生金石交，所贵在黄发。","同衾异寒燠，抱蕴应未察。","贫贱张与陈，利达胡与越。","安得皎洁心，长年似明月。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-fab52358-fe8e-45eb-8c4b-1c0c3bc524bb","tags":[]},{"id":"poem-aec101a4c6f8594284423400","title":"东门之池","author":"佚名","dynasty":"先秦","verses":["东门之池，可以沤麻。彼美淑姬，可与晤歌。","东门之池，可以沤纻。彼美淑姬，可与晤语。","东门之池，可以沤菅。彼美淑姬，可与晤言。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-138","tags":[]},{"id":"poem-aec7f41ab8358b123b2d5e1d","title":"四松","author":"杜甫","dynasty":"唐","verses":["四松初移时，大抵三尺强。","别来忽三载，离立如人长。","会看根不拔，莫计枝凋伤。","幽色幸秀发，疎柯亦昂藏。","所插小藩篱，本亦有隄防。","终然掁拨损，得恡千叶黄。","敢为故林主，黎庶犹未康。","避贼今始归，春草满空堂。","览物叹衰谢，及兹慰凄凉。","清风为我起，洒面若微霜。","足以送老姿，聊侍偃盖张。","我生无根带，配尔亦茫茫。","有情且赋诗，事迹可两望。","勿矜千载后，惨澹蟠穹苍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-1762014e-d551-478c-8547-d0e2ac0caa6e","tags":[]},{"id":"poem-aeca31e574b833d2c27c7c97","title":"天台瀑布","author":"曹松","dynasty":"唐","verses":["万仞得名云瀑布，远看如织挂天台。","休疑宝尺难量度，直恐金刀易剪裁。","喷向林梢成夏雪，倾来石上作春雷。","欲知便是银河水，堕落人间合却廻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-e3381503-fa01-421e-844d-f5001c50b7cc","tags":[]},{"id":"poem-aeca9d057478f9c27046a586","title":"句  其二","author":"赵世昌","dynasty":"宋","verses":["一条横截红尘断，几曲遥通紫禁深。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-4a6425bc-5c97-414a-a5a6-b0b8c2125ce0","tags":[]},{"id":"poem-aecf25befe9eace9abcd8130","title":"春游值雨","author":"张旭","dynasty":"唐","verses":["欲寻轩槛列清尊，江上烟云向晚昏。","须倩东风吹散雨，明朝却待入华园。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-435557f1-47d2-4a79-9628-7957533e5e71","tags":[]},{"id":"poem-aed09c665fe4ba58d07cf3c3","title":"偈颂六十七首  其四五","author":"释原妙","dynasty":"宋","verses":["三千世界作炉，百亿须弥为炭。","生铁铸就禅和，炙得通身红烂。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-e18d1e4f-6555-41a0-83ce-56e89068b73e","tags":[]},{"id":"poem-aed1e655639da8ae9490ef76","title":"临江仙·自古齐山重九胜","author":"晁补之","dynasty":"宋","verses":["自古齐山重九胜，登临梦想依依。","偶来恰值菊花时。","难逢开口笑，须插满头归。","昨夜一江风色好，平明秋浦帆飞。","可怜如赴史君期。","且当酬令节，不用叹斜晖。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-226","tags":[]},{"id":"poem-aedc8ff46beb1858a97706df","title":"希文枕边谈诗谓律诗易工梦中与之辩诗以折其非既觉忘数字因足成之","author":"洪德章","dynasty":"宋","verses":["七步成诗语近谐，坛荒李杜乏奇才。","僧敲未敢一言定，鸟过曾安几字来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-7bf91d1b-2176-4fb4-9ab4-f916ca8f1c9a","tags":[]},{"id":"poem-aee109ababfea6bb1a0d1da3","title":"入直西苑","author":"纳兰性德","dynasty":"清","verses":["望里蓬瀛近，行来阆苑齐。","晴霞开碧沼，落月隐金堤。","叶密莺先觉，花繁径不迷。","笙歌回辇处，长在凤城西。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-243","tags":[]},{"id":"poem-aee5a5dd6a413a7ee5eb58a2","title":"郊庙歌辞 隐太子庙乐章 送神","author":"不详","dynasty":"唐","verses":["皇情悼往，祀议增设。","钟鼓铿锵，羽旄昭晰。","掌礼云备，司筵告彻。","乐以送神，灵其鉴阕。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-867ad8d9-f1b1-43a5-94d7-7dac74332b1f","tags":[]},{"id":"poem-aee8c1fa355cde223b903e7f","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["小姐，你曾和他共鸳衾，同象床。","直恁的你认不得他形共庞。","(旦)面貌身材果然厮像，行动举止没两样。","(外暗听。","丑)既认得真时合主张。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8338","tags":[]},{"id":"poem-aee8eff26d68a283a2b8aa11","title":"腊月二十二日渡湘登道乡台夜归得五绝  其一","author":"张栻","dynasty":"宋","verses":["三年不作山中客，才踏船舷眼便明。","曳杖直登千尺磴，尚欣脚力慰生平。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-1a16fa4f-703f-49f8-bbeb-6f80210f4512","tags":[]},{"id":"poem-aef156a757248dc09f9ed3a1","title":"长门怨三首 二","author":"刘皂","dynasty":"唐","verses":["宫殿沈沈月欲分，昭阳更漏不堪闻。","珊瑚枕上千行泪，不是思君是恨君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-d995cd69-6e1a-4f0d-bc9d-bbbedc747d33","tags":[]},{"id":"poem-aef2b4a044a2f6bb116f2b91","title":"踏莎行·小径红稀","author":"晏殊","dynasty":"宋","verses":["小径红稀，芳郊绿遍。","高台树色阴阴见。","春风不解禁杨花，乱扑行人面。","翠叶藏莺，朱帘隔燕。","炉香静逐游丝转。","一场愁梦酒醒时，斜阳却照深深院。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-166","tags":["宋词三百首"]},{"id":"poem-aef37338c7162ee8f4071e2b","title":"梁州第七","author":"杨景贤","dynasty":"元","verses":["唐虞禅天垂雍穆，汤武圣民脱灾危。","周公制作非容易。","春秋无道，振起宣尼，获麟绝笔，轲也闻知。","笑六王竞角雌雄，叹吕政任了高斯，困重瞳马上英风。","更有那三分鼎峙，卧龙把炎精扶起。","晋移魏，如儿戏，纷纷五代自诛夷，怎胜得俺山水幽微。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-10312","tags":[]},{"id":"poem-aef618699aaa86154126db5b","title":"寄赠永嘉郑先生","author":"华镇","dynasty":"宋","verses":["荥阳人物世仍有，文雅风流传巳久。","广文独步天宝年，才名曾在诸公右。","新诗高陪屈宋游，神翰远与钟王偶。","更觉丹青到微妙，独将造化争妍丑。","一封入奏蓬莱宫，三绝题自君王手。","当时盛事虽云远，今日高风曾未朽。","亲逢夫子沧海头，重起清芬百年后。","倦游不肯依梁苑，尚德自甘耕谷口。","方外聪明已木鸡，人间事变皆刍狗。","子云寂寞守儋石，靖节轩昂遗五斗。","不试惟令曲艺工，久幽更觉机神厚。","诗情渺与江湘迥，画笔能教鬼神走。","论工子建已知亲，较胜长康未应负。","所嗟藻鉴阔楚越，犹使佳名在林薮。","邂逅虽知近岩壑，栖迟尚苦拘尘垢。","明明冰玉长在怀，望望烟霞屡骧首。","何日倾心听诵诗，他时洗眼看挥帚。","狂歌且寄草堂客，佳句终惭杜陵叟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-b5a41765-85be-4015-b877-97685d0a201f","tags":[]},{"id":"poem-aef621b4a36ca8c0789923cc","title":"寒食郊外","author":"贯休","dynasty":"唐","verses":["寒食将吾族，相随过石溪。","冢花沾酒落，林鸟学人啼。","白水穿芜疾，新霞出雾低。","不堪回首望，家在赤松西。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-2c940534-e56b-470c-8637-7b727a602811","tags":[]},{"id":"poem-aef76d902c8cc2c21764486e","title":"郊庙歌辞 梁太庙乐舞辞 大合舞","author":"不详","dynasty":"唐","verses":["於穆皇祖，濬哲雍熙。","美溢中夏，化被南陲。","后稷累德，公刘创基。","肇兴九庙，乐合来仪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-f87f89bd-21a1-4861-9590-eb27a2888aa2","tags":[]},{"id":"poem-af0f18e2ef3a89a85c8994b7","title":"九华观废月池","author":"薛逢","dynasty":"唐","verses":["曾发箫声水槛前，夜蟾寒沼两婵娟。","微波有恨终归海，明月无情却上天。","白鸟带将林外雪，绿荷枯尽渚中莲。","荣华不肯人间住，须读庄生第一篇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-6f35d619-7910-4914-82cc-1ee193b68b2e","tags":[]},{"id":"poem-af1028395980086e83f19d44","title":"谷口书斋寄杨补阙","author":"钱起","dynasty":"唐","verses":["泉壑带茅茨，云霞生薜帷。","竹怜新雨后，山爱夕阳时。","闲鹭栖常早，秋花落更迟。","家童扫萝迳，昨与故人期。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-b700208d-d859-4e36-96bf-883c81d4df0f","tags":["唐诗三百首","写景","五言律诗","邀请"]},{"id":"poem-af1e81d53edb5a572b23658e","title":"听琴","author":"张乔","dynasty":"唐","verses":["清月转瑶轸，弄中湘水寒。","能令坐来客，不语自相看。","静恐鬼神出，急疑风雨残。","几时归岭峤，更过洞庭弹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-2d9c9d0b-eb38-4239-a506-d237cd207139","tags":["洞庭湖"]},{"id":"poem-af2798105cfa85f8480bbf95","title":"度关山","author":"曹操","dynasty":"汉","verses":["天地间，人为贵。","立君牧民，为之轨则。","车辙马迹，经纬四极。","黜陟幽明，黎庶繁息。","于铄贤圣，总统邦域。","封建五爵，井田刑狱。","有燔丹书，无普赦赎。","皋陶甫侯，何有失职？","嗟哉后世，改制易律。","劳民为君，役赋其力。","舜漆食器，畔者十国，不及唐尧，采椽不斫。","世叹伯夷，欲以厉俗。","侈恶之大，俭为共德。","许由推让，岂有讼曲？","兼爱尚同，疏者为戚。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-0","tags":[]},{"id":"poem-af2c5f6a82ddb9e2facc10df","title":"和宣州钱判官使院厅前石楠树","author":"孟郊","dynasty":"唐","verses":["大朴既一剖，众材争万殊。","懿兹南海华，来与北壤俱。","生长如自惜，雪霜无凋渝。","笼笼抱灵秀，簇簇抽芳肤。","寒日吐丹艳，頳子流细珠。","鸳鸯花数重，翡翠叶四铺。","雨洗新妆色，一枝如一姝。","耸异敷庭际，倾妍来坐隅。","散彩饰机案，余辉盈盘盂。","高意因造化，常情逐荣枯。","主公方寸中，陶植在须臾。","养此奉君子，赏觌日为娱。","始觉石楠咏，价倾赋两都。","棠颂庶可比，桂词难以逾。","因谢丘墟木，空采落泥涂。","时来开佳姿，道去卧枯株。","争芳无由缘，受气如郁纡。","抽肝在郢匠，叹息何踟蹰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-e2be0d75-9a58-48a4-99d8-c73f3ea0e2ed","tags":[]},{"id":"poem-af3302b1dbfc9397cb4c9304","title":"池上宿","author":"刘得仁","dynasty":"唐","verses":["事事不求奢，长吟省叹嗟。","无才堪世弃，有句向谁夸。","老树呈秋色，空池浸月华。","凉风白露夕，此境属诗家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-2b0aeb3c-26cd-40cf-98ec-6d898b7d2bf4","tags":[]},{"id":"poem-af41d09fe8b115021a9f2894","title":"清平乐·春光欲暮","author":"毛熙震","dynasty":"五代","verses":["春光欲暮，寂寞闲庭户。","粉蝶双双穿槛舞，帘卷晚天疏雨。","含愁独倚闺帷，玉炉烟断香微。","正是销魂时节，东风满树花飞。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-46","tags":[]},{"id":"poem-af439f1c9445bf8a650dbc20","title":"寄白子元","author":"宋伯仁","dynasty":"宋","verses":["一番书满两番求，千里重来我更羞。","薄世告人难启口，小官何事不担忧。","知心唯有长天月，把酒还思故国秋。","只待菊花开遍了，半蓑寒雨上轻舟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-3a2a600d-d47a-44ce-b129-f000efbf598b","tags":[]},{"id":"poem-af4449f812910c89a080e7ec","title":"独坐看海棠二绝  其二","author":"王柏","dynasty":"宋","verses":["沈香亭下太真妃，一笑嫣然国已危。","当日杜陵深有恨，何心更作海棠诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-2eceb8ae-a0be-4217-a1c9-ac516d24a412","tags":[]},{"id":"poem-af4528a3a8c002c042069513","title":"赠张德恭","author":"陈造","dynasty":"宋","verses":["少日试推敲，未脱蜂鹤病。","世间十全手，噬肯爱三请。","即今悔少作，草草生气盛。","逢人忍修缩，拜手博是正。","往往掉其臂，百叩不一应。","赑屭仰前修，萎惫不能劲。","从君父子游，似颇识蹊径。","使君唾隋珠，枚叟每后乘。","郎君撞烟楼，楚珩复相映。","两豪五字律，万象一清镜。","賸馥副群趋，余风振不竞。","邮城望迎銮，未敢惮奔命。","向来从渠后，无乃莹吾听。","回省多岐亡，满冀一语订。","此篇尤爱我，见推乃见警。","政使元白前，向君亦修敬。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-e5be0db8-fc18-43cc-9a81-ee982ddbfbd3","tags":[]},{"id":"poem-af45c7317a7fcfd5795fe607","title":"中秋","author":"李朴","dynasty":"宋","verses":["皓魄当空宝镜升，云间仙籁寂无声。","平分秋色一轮满，长伴云衢千里明。","狡兔空从弦外落，妖蟆休向眼前生。","灵槎拟约同携手，更待银河澈底清。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-中秋","tags":[]},{"id":"poem-af47f3bd4f311c49baf1df5f","title":"忆水芙蓉木芙蓉寄西湖诸友  其二","author":"释居简","dynasty":"宋","verses":["花满秋城闯水明，镜中滴露掌中零。","曾雠新咏游花下，写寄城中石与丁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-5e693bc0-8d31-46fc-b4f3-4d13de09d5be","tags":["西湖"]},{"id":"poem-af4c2e847c8e7b7889605e80","title":"水阁纳凉","author":"王镃","dynasty":"宋","verses":["云碧纱厨水阁中，鸳鸯花冷枕玲珑。","描金团扇无人用，一阵荷香一阵风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-e53e7318-0262-4f63-9a11-a646172a89fd","tags":[]},{"id":"poem-af5f057386027261e9acc7ec","title":"溪村晚望","author":"王镃","dynasty":"宋","verses":["宿鹭分行落照边，村藏深树远吹烟。","天然诗句无人识，划记寒沙抄一篇。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-bfa4d0af-82ff-48e2-96aa-3e8a976500b6","tags":[]},{"id":"poem-af6256b6a8490673a4ba4c09","title":"卢蒲江雪夜约同直省中出示采菊读书煎茶种橘四诗索危秘书诸名胜同赋  其一","author":"释居简","dynasty":"宋","verses":["拙须务速巧须迟，尽巧依稀与拙宜。","除却艺兰纫楚佩，反骚只有落英诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-a16bf879-690a-4dbd-b512-225978033f7d","tags":[]},{"id":"poem-af63b94332cf4c0eac130b71","title":"十二时歌","author":"文偃","dynasty":"唐","verses":["夜半子，愚夫说相似。","鸡鸣丑，痴人捧龟首。","平旦寅，晓何人。","日出卯，韩情枯骨咬。","食时辰，历历明机是悟（《古尊宿语当》卷十五引作「悮」）真。","禺中巳，去来南北子。","日南午，认向途中苦。","日昳未，夏逢说寒气。","晡时申，张三李四会言真。","日入酉，恒机何得守。","黄昏戌，看见时光谁受屈。","人定亥，直（一作「真」）得分明沉苦海。","（见《大正新修大藏经》第四十七册宋僧守坚集《云门匡真禅师广录》卷上。","此条承王小盾同志告知。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-f763a41f-bb88-44f6-95ca-db3a5e8d7948","tags":[]},{"id":"poem-af6757cf7a99cfcb4fe3a671","title":"和子骏新荷","author":"司马光","dynasty":"宋","verses":["懒不窥园久，元非效仲舒。","新荷满沼密，蓝舁出门疏。","借问含烟晚，能胜裛露初。","愧无鱼戏句，弄翰白纷如。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-1a463b78-47d3-4bb2-bd6c-e1da993ce574","tags":[]},{"id":"poem-af6874fdb06df065a804aabb","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["叫天不应地不闻，腹中遍身疼怎忍？料想分娩在今宵，没个人来问。","望祖宗阴显应，保母子两身轻。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8922","tags":[]},{"id":"poem-af69ee6c62d9d382b925d9d5","title":"寄积麦山会如长老","author":"可止","dynasty":"唐","verses":["默然如大道，尘世不相关。","青桧行时静，白云禅处闲。","贫高一生行，病长十年颜。","夏满期游寺，寻山又下山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-c822084a-85dc-480d-913e-bd07cb3d1fab","tags":[]},{"id":"poem-af6b15c474924b0c4f38cd83","title":"凯风","author":"佚名","dynasty":"先秦","verses":["凯风自南，吹彼棘心。棘心夭夭，母氏劬劳。","凯风自南，吹彼棘薪。母氏圣善，我无令人。","爰有寒痊？在浚之下。有子七人，母氏劳苦。","𪾢睆黄鸟，载好其音。有子七人，莫慰母心。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-31","tags":[]},{"id":"poem-af710c6dd4a0405212440e71","title":"步出夏门行 冬十月","author":"曹操","dynasty":"汉","verses":["孟冬十月，北风徘徊，天气肃清，繁霜霏霏。","鹍鸡晨鸣，鸿雁南飞，鸷鸟潜藏，熊罴窟栖。","钱镈停置，农收积场。","逆旅整设，以通贾商。","幸甚至哉！歌以咏志。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-22","tags":[]},{"id":"poem-af77ac7602aab7a03f9c0170","title":"小游仙诗九十八首 六十一","author":"曹唐","dynasty":"唐","verses":["绛节笙歌绕殿飞，紫皇欲到五云归。","细腰侍女瑶花外，争向红房报玉妃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-e4178a61-f447-43b9-8eb7-3d047c211a9d","tags":[]},{"id":"poem-af7a07707156bc42d61e6f95","title":"春晚书山家屋壁二首 二","author":"贯休","dynasty":"唐","verses":["水香塘黑蒲森森，鸳鸯㶉𫛶如家禽。","前村后垄桑柘深，东邻西舍无相侵。","蚕娘洗茧前溪渌，牧童吹笛和衣浴。","山翁留我宿又宿，笑指西坡瓜豆熟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-ca89ed95-a370-4413-ad31-55a752465d07","tags":["山","写景","抒情","喜悦","组诗","乡村"]},{"id":"poem-af845a595381b44a53ff9f21","title":"代人与荆襄李制帅","author":"释居简","dynasty":"宋","verses":["桃花武陵原，千骑访旧游。","旧题鬼神护，苔藓封蛟虬。","是时原中花，炫昼烂不收。","稚耄相懽呼，再拜罗道周。","一闻謦咳声，曰似吾故侯。","侯今飞上天，盟在沧江鸥。","公来席未温，玉帐凉生秋。","粘天洞庭北，襄楚当襟喉。","小屈经纶手，平分宵旰忧。","风清鹦鹉洲，月满黄鹤楼。","黄鹤去不返，万灶栖貔貅。","白羽青纶巾，坐寝淮南谋。","文武固一道，貂蝉出兜鍪。","致身须黄阁，看镜方黑头。","故家迈种德，台辅不足酬。","颓支邹鲁澜，末障洙泗流。","载观统有宗，抑使俗不浮。","古道复大明，殊俗皆蒙休。","况夫蜀文章，眉独称雄酋。","多应峩眉月，只照东家丘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-32a2d444-dc48-435d-92f2-4b56a76f32b1","tags":["洞庭湖"]},{"id":"poem-af8a86fa0a39d27de5430add","title":"依韵赠南安方处士五首 二","author":"徐夤","dynasty":"唐","verses":["休把羸蹄蹋霜雪，书成何处献君王。","嵩山好与浮丘约，三十六峰云外乡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-0ef07fbb-9021-4200-9b1a-1a07f721f004","tags":[]},{"id":"poem-af8c5098ae209c9243d5a4f7","title":"春秋战国门 宋子罕","author":"周昙","dynasty":"唐","verses":["子怜温润欲归仁，吾贵坚廉是宝身。","自有不贪身内宝，玉人徒献外来珍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-f5d184fc-ff85-46a1-877d-95bca6ecab45","tags":[]},{"id":"poem-af94bb7a3c54104bb5a6d3ae","title":"仙吕/赏花时","author":"杨景贤","dynasty":"元","verses":["放鱼的都言子产良，射虎的皆称周处强。","你之任到他乡，买得活鱼尚不忍坏，今恩足以及禽兽矣。","百姓行必有个主张，咱两个携手上河梁。","(下)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-7936","tags":[]},{"id":"poem-af9a3ebfec5c9bb607cc10c6","title":"送人南归","author":"李益","dynasty":"唐","verses":["人言下江疾，君道下江迟。","五月江路恶，南风惊浪时。","应知近家喜，还有异乡悲。","无奈孤舟夕，山歌闻竹枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-8b4c8085-3507-4d7d-b0d0-23b86cde36d1","tags":[]},{"id":"poem-afa8f4377523d1e679276e5e","title":"玉楼春·三衢太守文章伯","author":"毛滂","dynasty":"宋","verses":["三衢太守文章伯。","七月政成如戏剧。","坐中咳唾落珠玑，笔下神明飞霹雳。","才高莫恨溪山窄。","且与燕公添秀发。","风流前辈渐无多，好在魏公门下客。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-767","tags":[]},{"id":"poem-afaada1167f003c801a36fbc","title":"送姪一斋游武林","author":"柴元彪","dynasty":"宋","verses":["舸鹢退飞杭不鱼，沧海翻覆桑田墟。","长安草木成焦枯，黯黯落日栖平芜。","凄凉往事增欷歔，子长一部太史书。","寄在名山大泽区，之子安肯侣樵渔。","有琴一张酒一壶，胸中云梦八九潴。","啮雪奔电千里途，大鹏击水九万图。","十年骑鹤来上都，宫鶑陌燕相喧呼。","回首一梦今何如，太行羊肠九折迂。","出门欲往如挛拘，顾予老矣仆马痡。","甘心首阳采薇夫，之子春风曳长裾。","西湖为我问讯学士苏，孤山为我起居处士逋。","二仙笑我犹故吾，杨柳黯淡梅花癯。","之子此行出有车，抱材珍重如璠玙。","青萍出匣蛟可屠，白发倚门望不孤。","不妨早赋归来乎，归来兮，老莱斑衣膝下相欢娱。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-c301df73-5468-4cab-abfa-bed485abe167","tags":["西湖"]},{"id":"poem-afaf2a980a1783d99d2a612b","title":"对早梅寄友人二首 二","author":"崔道融","dynasty":"唐","verses":["忆得去年有遗恨，花前未醉到无花。","清芳一夜月通白，先脱寒衣送酒家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-d8351dd2-c045-42a4-ac5b-6ae504f541be","tags":[]},{"id":"poem-afb299d3c4d140e18c2db899","title":"和三乡诗","author":"陆贞洞","dynasty":"唐","verses":["惆怅残花怨暮春，孤鸾舞镜倍伤神。","清词好个干人事，疑是文姬第二身。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ad3af8c3-05b7-4885-a66b-41699c3ebd5c","tags":[]},{"id":"poem-afb96841eb926e30982f7387","title":"菩萨蛮·绣帘高轴临塘看","author":"毛熙震","dynasty":"五代","verses":["绣帘高轴临塘看，雨翻荷芰真珠散。","残暑晚初凉，轻风渡水香。","无聊悲往事，怎奈牵情思。","光景暗相催，等闲秋又来。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-11","tags":[]},{"id":"poem-afbf6abb91d794a7ca238c65","title":"山居夏日","author":"高骈","dynasty":"唐","verses":["绿树阴浓夏日长，楼台倒影入池塘。","水晶帘动微风起，满架蔷薇一院香。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-山居夏日","tags":[]},{"id":"poem-afc539be608190c88a82c380","title":"上南都权府提刑孙大监二首  其二","author":"华镇","dynasty":"宋","verses":["抠衣平昔登门下，曾许横经近绛纱。","江上一言冰玉远，天涯长叹水云赊。","不才漫忝朱为绂，承学终惭发已华。","今日姓名犹见齿，尚因提奖得灵槎。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-177152d8-7fb5-4c98-a861-f4e0c15e2bd6","tags":[]},{"id":"poem-afda6772e8eced07493ccab3","title":"金珑璁","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["饥荒先自窘。","那堪连丧双亲，身独自怎支分？衣衫都典尽，首饰并没分文，无计策剪香云。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5118","tags":[]},{"id":"poem-afdec66ece37cdc52c8c4038","title":"南岳庵僧寄上封新茶风味甚高薄暮分送韩廷玉李嵩老","author":"张栻","dynasty":"宋","verses":["浮瓯雪色喜初尝，中有祝融风露香。","径欲与君同晤赏，短檠清夜正相望。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-0601c8be-ce20-4fd4-876f-277e75575721","tags":["衡山"]},{"id":"poem-afdfdd6b7ad71fee4766f519","title":"舟中寒食","author":"卢纶","dynasty":"唐","verses":["寒食空江曲，孤舟渺水前。","鬬鸡沙鸟异，禁火岸花然。","日霁开愁望，波喧警醉眠。","因看数茎鬓，倍欲惜芳年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-6367bd53-1d65-492f-afae-57db79e5c812","tags":[]},{"id":"poem-afe04ca19dc8f7bc0fe3c9b0","title":"后宫词","author":"白居易","dynasty":"唐","verses":["泪湿罗巾梦不成，夜深前殿按歌声。","红颜未老恩先断，斜倚薰笼坐到明。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-549a5a94-a8f5-436e-bc9c-1253d01c1940","tags":["唐诗三百首","七言绝句","宫怨"]},{"id":"poem-aff373660f5d51ad12ec3195","title":"一剪梅・一翦梅·红藕香残玉簟秋","author":"李清照","dynasty":"宋","verses":["红藕香残玉簟秋。","轻解罗裳，独上兰舟。","雪中谁寄锦书来，雁字回时，月满西楼。","花自飘零水自流。","一种相思，两处闲愁。","此情无计可消除，才下眉头，却上心头。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-693","tags":[]},{"id":"poem-aff3b0617dc4724a96bece20","title":"雨后","author":"孙介","dynasty":"宋","verses":["呼童卷帘收架书，簷溜忽断云萧疎。","山光水影净如拭，一川秋意生芙蕖。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-6547bf3b-55e0-49e0-9788-1acc15c3ce2c","tags":[]},{"id":"poem-aff4532b45ca51130d49a94a","title":"送刘枢密留守建康","author":"张栻","dynasty":"宋","verses":["整驾欲南骛，乃复送公舟。","公行民所瞻，愿言勿淹留。","向来秉事枢，正色有忠谋。","坐觉国势尊，已验权纲收。","如何霖雨泽，偏使及南州。","新春紫诏下，闻者宽百忧。","谁升今重镇，百万宿貔貅。","控江抚长淮，声势接上流。","吾皇志经略，此地合绸缪。","不应万全策，岁月空悠悠。","先当植本根，次第施良筹。","未闻欲外攘，而乃忽内修。","幕府方宏开，人才要旁搜。","可不念葑菲，惟当别薰莸。","留钥岂淹久，即归侍前旒。","尽舒医国手，调瘵会有瘳。","还忆遐荒守，时能寄音不。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-69564fc3-515d-4cfb-b6c2-ce989bf2e533","tags":[]},{"id":"poem-affb9374b33e61a3cc5d1d36","title":"皇矣","author":"佚名","dynasty":"先秦","verses":["皇矣上帝，临下有赫。监观四方，求民之莫。维此二国，其政不获。","维彼四国，爰究爰度。上帝耆之，憎其式廓。乃眷西顾，此维与宅。","作之屏之，其菑其翳。修之平之，其灌其栵。启之辟之，其柽其椐。","攘之剔之，其檿其柘。帝迁明德，串夷载路。天立厥配，受命既固。","帝省其山，柞棫斯拔，松柏斯兑。帝作邦作对，自大伯王季。维此王季，因心则友。则友其兄，则笃其庆，载锡之光。受禄无丧，奄有四方。","维此王季，帝度其心。貊其德音，其德克明。克明克类，克长克君。","王此大邦，克顺克比。比于文王，其德靡悔。既受帝祉，施于孙子。","帝谓文王：无然畔援，无然歆羡，诞先登于岸。密人不恭，敢距大邦，侵阮徂共。王赫斯怒，爰整其旅，以按徂旅。以笃于周祜，以对于天下。","依其在京，侵自阮疆。陟我高冈，无矢我陵。我陵我阿，无饮我泉，我泉我池。度其鲜原，居岐之阳，在渭之将。万邦之方，下民之王。","帝谓文王：予怀明德，不大声以色，不长夏以革。不识不知，顺帝之则。","帝谓文王：訽尔仇方，同尔弟兄。以尔钩援，与尔临冲，以伐崇墉。","临冲闲闲，崇墉言言。执讯连连，攸馘安安。是类是祃，是致是附，四方以无侮。临冲茀茀，崇墉仡仡。是伐是四，是绝是忽。四方以无拂。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-240","tags":[]},{"id":"poem-b011d0e4fb59d9088259d2fd","title":"下第献座主张谓","author":"阎济美","dynasty":"唐","verses":["謇谔王臣直，文明雅量全。","望炉金自跃，应物镜何偏。","南国幽沈尽，东堂礼乐宣。","转令游艺士，更惜至公年。","芳树欢新景，青云泣暮天。","唯愁凤池拜，孤贱更谁怜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-1595f1a9-d8fb-4b39-a406-c242b0e47ba7","tags":[]},{"id":"poem-b0126a69ea488ca69ba277ef","title":"梅","author":"王淇","dynasty":"宋","verses":["不受尘埃半点侵，竹篱茅舍自甘心。","只因误识林和靖，惹得诗人说到今。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-梅","tags":[]},{"id":"poem-b01d99aac9961afc3e54ccaa","title":"后苦寒行二首 二","author":"杜甫","dynasty":"唐","verses":["晚来江门失大木，猛风中夜吹白屋。","天兵斩断青海戎，杀气南行动地轴，不尔苦寒何太酷。","巴东之峡生凌澌，彼苍回轩人得知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-ad408522-3d66-49f7-be14-8ca7a8d29301","tags":[]},{"id":"poem-b01dc64e22023b58a1e5d1ce","title":"凤栖梧・蝶恋花·伫倚危楼风细细","author":"柳永","dynasty":"宋","verses":["伫倚危楼风细细。","望极春愁，黯黯生天际。","草色烟光残照里。","无言谁会凭阑意。","拟把疏狂图一醉。","对酒当歌，强乐还无味。","衣带渐宽终不悔。","为伊消得人憔悴。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-144","tags":["宋词三百首"]},{"id":"poem-b020328b8774192fd578ff81","title":"蝶恋花·漏泄东君消息后","author":"方千里","dynasty":"宋","verses":["漏泄东君消息后。","短叶长条，著意遮轩牖。","嫩比鹅黄初熟酒。","染匀巧费春风手。","万缕筛金新月透。","入夜柔情，还胜朝来秀。","彩笔雕章知几首。","可人标韵无新旧。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-561","tags":[]},{"id":"poem-b023088793f0123f7d863b75","title":"更漏子 其四","author":"温庭筠","dynasty":"唐","verses":["相见稀，相忆久，眉浅淡烟如柳。","垂翠幕，结同心，待郎熏绣衾。","城上月，白如雪，蝉鬓美人愁绝。","宫树暗，鹊桥横，玉签初报明。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-17","tags":[]},{"id":"poem-b025f9e2939381251c173640","title":"题清彻上人院","author":"张籍","dynasty":"唐","verses":["古寺临坛久，松间别起堂。","看添浴佛水，自合读经香。","爱养无家客，多传得效方。","过斋长不出，坐卧一绳床。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-a4fbbd3e-4001-421f-9a95-b300d522bada","tags":[]},{"id":"poem-b03003a9189218fb7a14b872","title":"酒泉子·杨柳舞风","author":"顾敻","dynasty":"五代","verses":["杨柳舞风，轻惹春烟残雨。","杏花愁，莺正语，画楼东。","锦屏寂寞思无穷，还是不知消息。","镜尘生，珠泪滴，损仪容。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-8","tags":[]},{"id":"poem-b03c4163910e9e3024f88ec6","title":"逍遥乐·春意渐归芳草","author":"黄庭坚","dynasty":"宋","verses":["春意渐归芳草。","故国佳人，千里信沈音杳。","雨润烟光，晚景澄明，极目危栏斜照。","梦当年少。","对樽前、上客邹枚，小鬟燕赵。","共舞雪歌尘，醉里谈笑。","花色枝枝争好。","鬓丝年年渐老。","如今遇风景，空瘦损、向谁道。","东君幸赐与，天幕翠遮红绕。","休休，醉乡歧路，华胥蓬岛。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-774","tags":[]},{"id":"poem-b03d605bf734143e82f2fcc6","title":"杨柳枝二首 二","author":"司空图","dynasty":"唐","verses":["数枝珍重蘸沧浪，无限尘心暂免忙。","烦暑若和烟露裛，便同佛手洒清凉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-6da4721a-bf15-4aac-895e-db29bbadccd6","tags":[]},{"id":"poem-b040f2c3b5a35563d11006cc","title":"前腔换头","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["乡官可怜见，这是公婆命所关。","若是必须将去，宁可脱了奴衣裳，就问乡官换。","(丑白)不要，你身上寒冷。","(旦唱)宁使奴，身上寒。","只要与公婆，救残喘。","(丑夺谷介下)(旦介唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5043","tags":[]},{"id":"poem-b04299bee8298a4f12f69b88","title":"丑奴儿・采桑子·年年有个人生日","author":"张孝祥","dynasty":"宋","verses":["年年有个人生日，谁似君家。","谁似君家。","八十慈亲发未华。","棠阴阁上棠阴满，满劝流霞。","满劝流霞。","来岁应添宰路沙。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-272","tags":[]},{"id":"poem-b06f1e814e3fd5fb00c5543d","title":"后出塞五首 四","author":"杜甫","dynasty":"唐","verses":["献凯日继踵，两蕃静无虞。","渔阳豪侠地，击鼓吹笙竽。","云帆转辽海，稉稻来东吴。","越罗与楚练，照耀舆台躯。","主将位益崇，气骄凌上都。","边人不敢议，议者死路衢。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-74e31da9-682f-45e2-8c18-c5a5689c3ba9","tags":[]},{"id":"poem-b070432eca33d6ba5f2aefb6","title":"述怀","author":"李愚","dynasty":"唐","verses":["奉职常如履薄冰，屡看斜日下觚棱。","盐梅且让当朝杰，粥饭甘为退院僧。","虚负紫宸思宠渥，自伤白发病侵凌。","明年便向燕南去，竹坞云庵独枕肱。","（见民国十四年刊张方墀纂《无棣县志》卷二十三。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-287a6687-8493-40a9-ba6c-24a13e29f01e","tags":[]},{"id":"poem-b070751d8d267c8cb9b3dea4","title":"鼓吹曲辞 将进酒","author":"李白","dynasty":"唐","verses":["君不见黄河之水天上来，奔流到海不复回。","君不见高堂明镜悲白发，朝如青丝暮成雪。","人生得意须尽欢，莫使金尊空对月。","天生我材必有用，千金散尽还复来。","烹羊宰牛且为乐，会须一饮三百杯。","岑夫子，丹丘生，将进酒，杯莫停。","与君歌一曲，请君为我侧耳听。","钟鼓馔玉不足贵，但愿长醉不复醒。","古来圣贤皆寂寞，惟有饮者留其名。","陈王昔时宴平乐，斗酒十千恣欢谑。","主人何为言少钱，径须酤取对君酌。","五花马，千金裘，呼儿将出换美酒，与尔同销万古愁。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-0f7504df-cda2-4fe2-bc63-867ec2e418e7","tags":["唐诗三百首","黄河","咏物","抒情","鼓吹曲辞","乐府","宴饮","哲理","水","咏物诗"]},{"id":"poem-b071072e330c1226c827dd83","title":"小重山·雨过风来午暑清","author":"米友仁","dynasty":"宋","verses":["雨过风来午暑清。","榴花红照眼，向人明。","一枝低映宝钗横。","菖蒲酒，玉碗十分斟。","引满听新声。","小轩帘半卷，远山青。","几人闲处见闲情。","醒还醉，为趣妙难名。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-63","tags":[]},{"id":"poem-b0712f145c5a035711abc4d4","title":"观碁","author":"子兰","dynasty":"唐","verses":["拂局尽消时，能因长路迟。","点头初得计，格手待无疑。","寂默亲遗景，凝神入过思。","共藏多少意，不语两相知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-07a74718-94be-41f9-a43a-5c30490492f1","tags":[]},{"id":"poem-b07428be7135e8640fff1a9d","title":"常武","author":"佚名","dynasty":"先秦","verses":["赫赫明明。王命卿士，南仲大祖，大师皇父。整我六师，以修我戎。既敬既戒，惠此南国。","王谓尹氏，命程伯休父，左右陈行。戒我师旅，率彼淮浦，省此徐土。不留不处，三事就绪。","赫赫业业，有严天子。王舒保作，匪绍匪游。徐方绎骚，震惊徐方。如雷如霆，徐方震惊。","王奋厥武，如震如怒。进厥虎臣，阚如虓虎。铺敦淮𣸣，仍执丑虏。截彼淮浦，王师之所。","王旅啴啴，如飞如翰。如江如汉，如山之苞。如川之流，绵绵翼翼。不测不克，濯征徐国。","王犹允塞，徐方既来。徐方既同，天子之功。四方既平，徐方来庭。徐方不回，王曰还归。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-262","tags":[]},{"id":"poem-b07697f86607baf8cf0b7842","title":"·","author":"用虚","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-08c1efbb-6674-4a66-bfeb-1312d040aae6","tags":[]},{"id":"poem-b076c971ed01770ae2ff9506","title":"赋得有所思","author":"徐铉","dynasty":"宋","verses":["所思何在杳难寻，路远山长水复深。","衰草满庭空伫立，清风吹袂更长吟。","忘情好醉青田酒，寄恨宜调绿绮琴。","落日鲜云偏聚散，可能知我独伤心。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-e0ad75a4-79e4-4b73-b7b8-15eb1c0b7568","tags":[]},{"id":"poem-b079a4a967f0d1936d4bd27e","title":"家兄有和再用韵  其三","author":"艾可翁","dynasty":"宋","verses":["乱离生世晚，衰白在人前。","云水飞饥鹤，山林付乱蝉。","日今行黑道，人有隔黄泉。","晷渐秋来短，愁长亦敌年。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-222ed8d0-26f5-4148-b107-e9b4b5424ad2","tags":[]},{"id":"poem-b07ce80460e0f851e8450f9e","title":"挽张约之","author":"华镇","dynasty":"宋","verses":["盗跖有年颜子夭，千秋此理竟难昭。","一枝仙果方成实，三叶阶兰已尽凋。","壮志永违祇自恨，清魂一去更谁招。","犹胜伯道终身后，应得幽冥慰寂寥。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-9ab8410b-53ac-41e3-b879-40d754d4a74a","tags":[]},{"id":"poem-b082f36c235c29f7165c8d9a","title":"寻裴处士","author":"孟郊","dynasty":"唐","verses":["涉水更登陆，所向皆清真。","寒草不藏径，灵峰知有人。","悠哉炼金客，独与烟霞亲。","曾是欲轻举，谁言空隐沦。","远心寄白月，华发回青春。","对此钦胜事，胡为劳我身。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-e14f3acb-c22f-42cb-93ec-d2550512ecb7","tags":[]},{"id":"poem-b08ba49e5d14d79a31418136","title":"句  其四","author":"林敏功","dynasty":"宋","verses":["竹闲初折半斜枝。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-20c039a2-425d-479b-9f69-269b3ad0287e","tags":[]},{"id":"poem-b09585dd878eef4acece3f75","title":"夜夜曲","author":"贯休","dynasty":"唐","verses":["蟪蛄切切风骚骚，芙蓉喷香蟾蜍高。","孤灯耿耿征妇劳，更深扑落金错刀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-2a3c5a70-a796-46d2-8f22-87c21636da0e","tags":[]},{"id":"poem-b09ded7886401ce20d7e894f","title":"鹧鸪天·闲立飞虹远兴长","author":"张镃","dynasty":"宋","verses":["闲立飞虹远兴长。","一方云锦荐疏凉。","翻风翠盖无尘土，出水红妆有艳香。","携靓侣，泛轻航。","棹歌惊起野鸳鸯。","同过清夏看新月，茉莉花园小象床。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-361","tags":[]},{"id":"poem-b09f9ab364c39e277ae4779d","title":"奉和圣制荅二相出雀鼠谷","author":"徐安贞","dynasty":"唐","verses":["两臣初入梦，二月扈巡边。","涧北寒犹在，山南春半传。","颂声先奉御，辰象复回天。","云日明千里，旌旗照一川。","柳阴低辇路，草色变新田。","还望汾阳近，宸游自窅然。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-46e9e27f-0f28-4152-8c32-05d172246cfa","tags":[]},{"id":"poem-b0a3e398ca4310bb2f5196a0","title":"浣溪沙·独立寒阶望月华","author":"张泌","dynasty":"五代","verses":["独立寒阶望月华，露浓香泛小庭花，绣屏愁背一灯斜。","云雨自从分散后，人间无路到仙家，但凭魂梦访天涯。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-29","tags":[]},{"id":"poem-b0a6a103b59886e7f1973972","title":"游鱼","author":"来鹄","dynasty":"唐","verses":["弄萍隈荇思夷犹，掉尾扬鬐逐慢流。","应怕碧岩岩下水，浮藤如线月如钩。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-5926bdfb-7c59-4ecf-9ec8-c6b6050227f1","tags":[]},{"id":"poem-b0b5883d344f88d804356896","title":"灞上秋居","author":"马戴","dynasty":"唐","verses":["灞原风雨定，晚见鴈行频。","落叶他乡树，寒灯独夜人。","空园白露滴，孤壁野僧隣。","寄卧郊扉久，何门致此身。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-f2f04c30-149d-4b2b-bce1-1334adf84739","tags":["唐诗三百首","孤独","秋天","五言律诗","怀才不遇"]},{"id":"poem-b0b5a6a6f3f76917f84c68ad","title":"绮罗香·做冷欺花","author":"史达祖","dynasty":"宋","verses":["做冷欺花，将烟困柳，千里偷催春暮。","尽日冥迷，愁里欲飞还住。","惊粉重、蝶宿西园，喜泥润、燕归南浦。","最妨它、佳约风流，钿车不到杜陵路。","沈沈江上望极，还被春潮晚急，难寻官渡。","隐约遥峰，和泪谢娘眉妩。","临断岸、新绿生时，是落红、带愁流处。","记当日、门掩梨花，翦灯深夜语。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-178","tags":["宋词三百首"]},{"id":"poem-b0b64b3a2ef888071c7ea068","title":"早春夜集耿拾遗宅","author":"李端","dynasty":"唐","verses":["如何逋客会，忽在侍臣家。","新草犹停雪，寒梅未放花。","衔杯鸡欲唱，逗月雁应斜。","年齿俱憔悴，谁堪故国赊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-48463e26-4422-448c-b3fa-d1245915026d","tags":[]}];
